class ScenarioSchemaError(TypeError):
    pass


class CandidateCompatibilityPoison(BaseException):
    pass


class CandidateRunnerPoison:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name

    def __call__(self, *args, **kwargs):
        raise CandidateCompatibilityPoison("runner unavailable: " + self.name)


class ScenarioContext:
    __slots__ = (
        "token",
        "events",
        "markers",
        "holders",
        "counters",
        "observables",
        "mutations",
    )

    def __init__(
        self,
        token,
        markers=(),
        holders=None,
        observables=None,
        events=None,
        mutations=(),
    ):
        self.token = token
        self.events = [] if events is None else events
        self.markers = tuple(markers)
        self.holders = OrderedDict() if holders is None else holders
        self.counters = OrderedDict()
        self.observables = OrderedDict() if observables is None else observables
        self.mutations = tuple(mutations)


class ScenarioAuthority:
    __slots__ = ("context", "name", "return_value", "marker", "expected_args")

    def __init__(
        self,
        context,
        name,
        return_value=None,
        marker=None,
        expected_args=None,
    ):
        self.context = context
        self.name = name
        self.return_value = return_value
        self.marker = marker
        self.expected_args = expected_args

    def __call__(self, *args, **kwargs):
        count = self.context.counters.get(self.name, 0) + 1
        self.context.counters[self.name] = count
        if self.expected_args is not None and args != self.expected_args:
            raise AssertionError("authority received unexpected production args")
        self.context.events.append(
            ("authority", self.name, count, len(args), tuple(kwargs))
        )
        self.context.holders[self.name + ":args"] = args
        self.context.holders[self.name + ":kwargs"] = OrderedDict(kwargs)
        if self.marker is not None:
            raise self.marker
        return self.return_value


