        (sessions_module.Session, "merge_environment_settings"),
        (sessions_module.Session, "send"),
        (sessions_module.SessionRedirectMixin, "get_redirect_target"),
        (sessions_module.SessionRedirectMixin, "should_strip_auth"),
        (sessions_module.SessionRedirectMixin, "rebuild_proxies"),
