original_chunked = sessions_module.ChunkedEncodingError
original_decoding = sessions_module.ContentDecodingError
original_runtime = sessions_module.__dict__.get("RuntimeError", RuntimeError)
original_too_many = sessions_module.TooManyRedirects
outcomes = []


class ContentResponse(Response):
    def __init__(self, request, marker, mode):
        super().__init__()
        self.request = request
        self.url = request.url
        self.status_code = 302
        self.headers = CaseInsensitiveDict({"location": "/next"})
        self.history = []
        self.raw = Raw(mode)
        self.marker = marker
        self.mode = mode

    @property
    def content(self):
        if self.mode == "matching":
            sessions_module.ChunkedEncodingError = type(self.marker)
        elif self.mode == "nonmatching":
            sessions_module.ChunkedEncodingError = KeyError
        elif self.mode == "deleted":
            sessions_module.__dict__.pop("ContentDecodingError", None)
        else:
            sessions_module.RuntimeError = object()
        raise self.marker

    def close(self):
        self.raw.events.append(["response-close"])


def run_mode(mode):
    request = prepared()
    marker = SystemExit(mode)
    response = ContentResponse(request, marker, mode)
    session = sessions_module.Session()
    session.max_redirects = 0 if mode == "matching" else 30
    try:
        try:
            next(session.resolve_redirects(response, request, yield_requests=True))
        except BaseException as error:
            record = error_record(error, marker)
    finally:
        sessions_module.ChunkedEncodingError = original_chunked
        sessions_module.ContentDecodingError = original_decoding
        sessions_module.RuntimeError = original_runtime
        sessions_module.TooManyRedirects = original_too_many
    return {"mode": mode, "error": record, "raw": response.raw.events, "history": len(response.history)}


def oracle_call():
    for mode in ["matching", "nonmatching", "deleted", "invalid"]:
        outcomes.append(run_mode(mode))
    assert outcomes[0]["error"]["type"][1] == "TooManyRedirects"
    assert outcomes[0]["history"] == 0
    assert outcomes[0]["raw"][0][0] == "read"
    assert outcomes[1]["error"]["is_sentinel"]
    assert outcomes[2]["error"]["type"] == ["builtins", "NameError"]
    assert outcomes[2]["error"]["context_is_sentinel"]
    assert outcomes[3]["error"]["type"] == ["builtins", "TypeError"]
    assert outcomes[3]["error"]["context_is_sentinel"]

    limit_rows = []

    class MutatingLimit:
        def __init__(self, owner):
            self.owner = owner

        def __le__(self, count):
            self.owner.max_redirects = "message-mutated"
            return True

    for label, limit in [
        ("negative", -1),
        ("bool", False),
        ("huge", 10**100),
        ("invalid", object()),
    ]:
        request = prepared()
        response = response_for(request, 302, "/next")
        session = sessions_module.Session()
        session.max_redirects = limit
        try:
            yielded = next(
                session.resolve_redirects(response, request, yield_requests=True)
            )
        except BaseException as error:
            limit_rows.append([label, error_record(error), None])
        else:
            limit_rows.append([label, None, yielded.url])

    request = prepared()
    response = response_for(request, 302, "/next")
    session = sessions_module.Session()
    session.max_redirects = MutatingLimit(session)
    try:
        next(session.resolve_redirects(response, request, yield_requests=True))
    except BaseException as error:
        custom = error_record(error)
    assert [row[1]["type"][1] if row[1] else None for row in limit_rows] == [
        "TooManyRedirects",
        "TooManyRedirects",
        None,
        "TypeError",
    ]
    assert custom["args"][0] == "Exceeded message-mutated redirects."
    return {"catchers": outcomes, "limits": limit_rows, "custom": custom}


