def digest_response(request, status, location=None, label="response"):
    returned = response_for(request, status, location, label, b"")
    if status == 401:
        returned.headers["www-authenticate"] = (
            'Digest realm="realm", nonce="nonce", qop="auth", algorithm="MD5"'
        )
    return returned


def run_chain(order):
    request = prepared("http://example.test/start")
    auth = HTTPDigestAuth("user", "password")
    request = auth(request)
    final = digest_response(prepared("http://example.test/final"), 200, label="final")
    if order == "401-redirect":
        redirect = digest_response(request, 302, "/next", "digest-redirect")
        first = digest_response(request, 401, label="first-401")
        first.connection = Connection(redirect, order)
        adapter = ScriptedAdapter([first, final], events, order)
    else:
        first = digest_response(request, 302, "/next", "first-redirect")
        unauthorized = digest_response(request, 401, label="redirect-401")
        unauthorized.connection = Connection(final, order)
        adapter = ScriptedAdapter([first, unauthorized], events, order)
    session = sessions_module.Session()
    session.trust_env = False
    install_only(session, "http://", adapter)
    returned = session.send(request, allow_redirects=True, stream=True)
    return {
        "order": order,
        "status": returned.status_code,
        "history": [item.status_code for item in returned.history],
        "authorization": "Authorization" in returned.request.headers,
    }


