_BASE_CASES = dict(_CASES)


def _base_case_parts(source: str) -> tuple[str, str, str, str]:
    normalized = dedent(source)
    tree = ast.parse(normalized)
    result_node = next(
        node
        for node in reversed(tree.body)
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name) and target.id == "result"
            for target in node.targets
        )
    )
    assert isinstance(result_node.value, ast.Call)
    assert isinstance(result_node.value.func, ast.Name)
    assert result_node.value.func.id == "case_result"
    call = result_node.value
    assert len(call.args) == 5
    lines = normalized.splitlines(keepends=True)
    prefix = "".join(lines[: result_node.lineno - 1]).rstrip()
    subject = ast.get_source_segment(normalized, call.args[1])
    operation = ast.get_source_segment(normalized, call.args[2])
    controls = ast.get_source_segment(normalized, call.args[3])
    assert subject is not None and operation is not None and controls is not None
    return prefix, subject, operation, controls


def _assemble_corrected_case(
    case_id: str, base_source: str, adversarial_source: str
) -> str:
    prefix, subject, operation, controls = _base_case_parts(base_source)
    final_source = f"""
{prefix}

_original_oracle_call = oracle_call

{dedent(adversarial_source).strip()}


def oracle_call():
    return {{
        "original": _original_oracle_call(),
        "adversarial": adversarial_oracle_call(),
    }}


combined_subject = {{
    "original": {subject},
    "adversarial": adversarial_subject,
}}
combined_controls = {{
    "contract": "phase-a-corrected-v5",
    "original": {controls},
    "adversarial": adversarial_controls,
}}
result = case_result(
    {case_id!r}, combined_subject, {operation}, combined_controls, oracle_call
)
"""
    return dedent(final_source)


