def m06_prepared_check(value):
    scenario = m06_active["scenario"]
    scenario.events.append("prepared-check")
    scenario.checked = value
    if scenario.stage == "prepared-check":
        raise scenario.marker
    return True


def m06_make(stage):
    scenario = SimpleNamespace(
        stage=stage,
        marker=BaseException("m06-" + stage),
        events=[],
        env_replaced=False,
        send_replaced=False,
        request=None,
        prepared=None,
        response=SimpleNamespace(label="m06-response-" + stage),
        constructor_kwargs=None,
        prepared_from=None,
        checked=None,
        env_args=None,
        send_args=None,
        decode_callback=None,
        original_decode=None,
        forbidden_decode=None,
    )
    def decode(encoding):
        scenario.events.append("decode-call")
        if scenario.stage == "decode-call":
            raise scenario.marker
        assert encoding == "utf-8"
        return "http://decoded.test/"

    def forbidden_decode(encoding):
        raise AssertionError("decode callback was reloaded after binding")

    scenario.original_decode = decode
    scenario.decode_callback = decode
    scenario.forbidden_decode = forbidden_decode
    scenario.prepared = M06Prepared(scenario)
    session = M06Session()
