m06_scenarios = [m06_make(stage) for stage in m06_stages]


def m06_run(scenario):
    stage = scenario.stage
    scenario.events.clear()
    scenario.env_replaced = False
    scenario.send_replaced = False
    scenario.request = None
    scenario.constructor_kwargs = None
    scenario.prepared_from = None
    scenario.checked = None
    scenario.env_args = None
    scenario.send_args = None
    scenario.decode_callback = scenario.original_decode
    data, params, proxies = scenario.inputs
    m06_active["scenario"] = scenario
    sessions_module.Request = m06_request_factory
    sessions_module._is_prepared = m06_prepared_check
    sessions_module.isinstance = m06_guard_isinstance
    sessions_module.bytes = M06Bytes
