class A06Session(sessions_module.Session):
    def __getattribute__(self, name):
        if name == "close":
            scenario = object.__getattribute__(self, "scenario")
            scenario.events.append(["close-bind", scenario.handler_name])
            if scenario.mode == "close-bind-error":
                raise scenario.close_marker
            retained = scenario.handler
            if scenario.mode == "retained-close":
                scenario.handler = scenario.forbidden
                scenario.handler_name = "forbidden"
            return retained
        return super().__getattribute__(name)

    def __exit__(self, *args):
        scenario = self.scenario
        scenario.events.append(
            [
                "exit-args",
                args[0] is type(scenario.body_marker) if args[0] is not None else None,
                args[1] is scenario.body_marker if args[1] is not None else None,
                args[2] is not None,
            ]
        )
        return super().__exit__(*args)


def a06_make(mode):
    scenario = SimpleNamespace(
        mode=mode,
        events=[],
        body_marker=BaseException("a06-body-" + mode),
        close_marker=BaseException("a06-close-" + mode),
        handler=None,
        handler_name="initial",
        forbidden=None,
    )

    def initial():
        scenario.events.append("initial-close")
        return "ignored-truthy-close-result"

    def replacement():
        scenario.events.append("replacement-close")
        if mode == "close-error":
            raise scenario.close_marker
        return "ignored-truthy-close-result"

    def forbidden():
        scenario.events.append("forbidden-close")
        raise AssertionError("retained close callable was replaced")

    scenario.initial = initial
    scenario.replacement = replacement
    scenario.handler = initial
    scenario.forbidden = forbidden
    scenario.session = A06Session()
    scenario.session.scenario = scenario
    return scenario


a06_scenarios = [
    a06_make(mode)
    for mode in [
        "return-none",
        "retained-close",
        "body-propagates",
        "close-error",
        "close-bind-error",
    ]
]


def a06_run(scenario):
    scenario.events.clear()
    scenario.handler = scenario.initial
    scenario.handler_name = "initial"
    session = scenario.session
    entered = sessions_module.Session.__enter__(session)
    assert entered is session
    if scenario.mode in {"return-none", "retained-close"}:
        returned = sessions_module.Session.__exit__(session, None, None, None)
        escaped = None
    else:
        try:
            with session as context_value:
                assert context_value is session
                scenario.handler = scenario.replacement
                scenario.handler_name = "replacement"
                raise scenario.body_marker
        except BaseException as error:
            escaped = error
        returned = None
    if escaped is None:
        record = None
        body_context = False
    else:
        sentinel = (
            scenario.close_marker
            if scenario.mode in {"close-error", "close-bind-error"}
            else scenario.body_marker
        )
        record = error_record(escaped, sentinel)
        body_context = escaped.__context__ is scenario.body_marker
    return {
        "mode": scenario.mode,
        "events": scenario.events,
        "enter_identity": entered is session,
        "return_is_none": returned is None,
        "error": record,
        "body_context": body_context,
    }


adversarial_subject = {
    "session_type": A06Session,
    "scenarios": a06_scenarios,
    "sessions": [scenario.session for scenario in a06_scenarios],
}
adversarial_controls = {
    "close_handlers": [
        [scenario.initial, scenario.replacement, scenario.forbidden]
        for scenario in a06_scenarios
    ]
}


def adversarial_oracle_call():
    rows = [a06_run(scenario) for scenario in a06_scenarios]
    return_none, retained, propagated, close_error, bind_error = rows
    assert return_none["events"] == [["close-bind", "initial"], "initial-close"]
    assert return_none["enter_identity"] and return_none["return_is_none"]
    assert retained["events"] == [["close-bind", "initial"], "initial-close"]
    assert "forbidden-close" not in retained["events"]
    assert propagated["events"] == [
        ["exit-args", True, True, True],
        ["close-bind", "replacement"],
        "replacement-close",
    ]
    assert propagated["error"]["is_sentinel"]
    assert propagated["error"]["type"] == ["builtins", "BaseException"]
    assert not propagated["body_context"]
    for row in [close_error, bind_error]:
        assert row["error"]["is_sentinel"]
        assert row["error"]["type"] == ["builtins", "BaseException"]
        assert row["error"]["traceback"] and row["body_context"]
        assert not row["error"]["cause"] and not row["error"]["suppress_context"]
    assert close_error["events"] == [
        ["exit-args", True, True, True],
        ["close-bind", "replacement"],
        "replacement-close",
    ]
    assert bind_error["events"] == [
        ["exit-args", True, True, True], ["close-bind", "replacement"]
    ]
    return {
        "return_none": return_none,
        "retained": retained,
        "propagated": propagated,
        "close_error": close_error,
        "bind_error": bind_error,
    }
