def v6_observer(
    subject,
    _all=all,
    _object=object,
    _ordered=OrderedDict,
    _dict=dict,
    _tuple=tuple,
    _list=list,
    _enumerate=enumerate,
    _str=str,
):
    context = _object.__getattribute__(subject[0], "context")
    holders = _object.__getattribute__(context, "holders")
    first_record = _ordered.__getitem__(holders, "first")
    set_auth_record = _ordered.__getitem__(holders, "set-auth")
    second_record = _ordered.__getitem__(holders, "second")
    disable_env_record = _ordered.__getitem__(holders, "disable-env")
    third_record = _ordered.__getitem__(holders, "third")
    assert _tuple.__getitem__(first_record, 0) == "return"
    assert _tuple.__getitem__(set_auth_record, 0) == "return"
    assert _tuple.__getitem__(set_auth_record, 1) is None
    assert _tuple.__getitem__(second_record, 0) == "return"
    assert _tuple.__getitem__(disable_env_record, 0) == "return"
    assert _tuple.__getitem__(disable_env_record, 1) is None
    assert _tuple.__getitem__(third_record, 0) == "return"
    first = _tuple.__getitem__(first_record, 1)
    second = _tuple.__getitem__(second_record, 1)
    third = _tuple.__getitem__(third_record, 1)
    first_headers = _object.__getattribute__(first, "headers")
    first_store = _object.__getattribute__(first_headers, "_store")
    authorization = _tuple.__getitem__(
        _ordered.__getitem__(first_store, "authorization"), 1
    )
    assert _str.startswith(authorization, "Basic ")
    second_headers = _object.__getattribute__(second, "headers")
    second_store = _object.__getattribute__(second_headers, "_store")
    second_authorization = _tuple.__getitem__(
        _ordered.__getitem__(second_store, "authorization"), 1
    )
    assert _str.startswith(second_authorization, "Basic ")
    assert second is not first
    third_headers = _object.__getattribute__(third, "headers")
    third_store = _object.__getattribute__(third_headers, "_store")
    assert "authorization" not in third_store
    counters = _object.__getattribute__(context, "counters")
    assert _ordered.__getitem__(counters, "netrc") == 2
    assert counters.get("auth-call", 0) == 0
    scenario = _tuple.__getitem__(subject, 0)
    actions = _object.__getattribute__(scenario, "actions")
    session = _object.__getattribute__(scenario, "receiver")
    assert _object.__getattribute__(session, "auth") is _object.__getattribute__(
        _tuple.__getitem__(actions, 1), "target"
    )
    assert _object.__getattribute__(session, "trust_env") is False
    return _list(_list.__iter__(_object.__getattribute__(context, "events")))


result = case_result(
    "M05", v6_subject, {operation}, v6_controls, v6_observer
)
