    def lower(self):
        self.state.context.events.append(["prefix-lower", self.index])
        if self.state.stage == "prefix-lower":
            raise self.state.marker
        if self.index == 1:
            if self.state.stage == "in-place":
                self.state.mapping[self.state.added_prefix] = self.state.added_adapter
            else:
                self.state.session.adapters = self.state.replacement
            self.state.url_mutated = True
        return "first://" if self.index == 1 else "second://"


