class V6A05Codec:
    __slots__ = (
        "state", "mode", "generation", "stop", "loads_token",
        "allocator_token", "session_type_token",
    )

    def __init__(
        self, state, mode, generation=1, stop=False, loads_token=None,
        allocator_token=None, session_type_token=None,
    ):
        self.state = state
        self.mode = mode
        self.generation = generation
        self.stop = stop
        self.loads_token = loads_token
        self.allocator_token = allocator_token
        self.session_type_token = session_type_token

    def __call__(self, value):
        codec = __import__("pickle")
        state = self.state
        label = "codec-" + self.mode
        if self.generation != 1:
            label += "-" + str(self.generation)
        if self.mode == "dumps":
            state.context.events.append([
                label, type(value) is dict, list(value)
            ])
        else:
            state.context.events.append([label, type(value) is bytes])
        module = __import__("requests.sessions", fromlist=["Session"])
        if self.loads_token is not None:
            module._v6_a05_loads = _v6_private_resolve(self.loads_token)
        if self.session_type_token is not None:
            module._v6_a05_session_type = _v6_private_resolve(
                self.session_type_token
            )
        if self.allocator_token is not None:
            module._v6_a05_allocate = _v6_private_resolve(
                self.allocator_token
            )
        if self.stop:
            raise state.marker
        if self.mode == "dumps":
            return codec.dumps(value)
        return codec.loads(value)


class V6A05Allocator:
    __slots__ = ("state", "generation", "stop")

    def __init__(self, state, generation=1, stop=False):
        self.state = state
