    def __call__(self, session_type):
        module = __import__("requests.sessions", fromlist=["Session"])
        label = "allocate"
        if self.generation != 1:
            label += "-" + str(self.generation)
        self.state.context.events.append([label, session_type is module.Session])
        if self.stop:
            raise self.state.marker
        return session_type.__new__(session_type)


