    v6_setup = tuple(Action("semantic-call", setter, "__call__", (replacement,), OrderedDict()) for setter, replacement in zip(v6_t07_setters, v6_replacements))
    v6_entry = native_operation(sessions_module.Session, "send", "t07-send")
    v6_args = (v6_state.session, v6_state.request)
