def v6_observer(
    subject,
    _all=all,
    _base_exception=BaseException,
    _enumerate=enumerate,
    _object=object,
    _ordered=OrderedDict,
    _snapshot=inspection_snapshot,
    _sum=sum,
    _tuple=tuple,
    _type=type,
    _outcomes=v6_outcomes,
):
    rows = []
    success_events = [
        "select", "clock-1", "adapter", "clock-2", "subtract",
        "timedelta", "conversion", "elapsed", "hook", "history-get-1",
        "history-truth", "history-get-2", "history-iteration", "jar-get-1",
        "request-get", "raw-get", "cookie-1", "jar-get-2", "cookie-2",
        "redirect-create", "redirect-iteration-1", "redirect-iteration-2",
        "stream", "content",
    ]
    for index, scenario in _enumerate(_tuple.__iter__(subject)):
        context = _object.__getattribute__(scenario, "context")
        holders = _object.__getattribute__(context, "holders")
        state = _ordered.__getitem__(holders, "state")
        mode = _object.__getattribute__(state, "mode")
        v6_transition_mutation_anchor = mode
        assert mode == v6_transition_mutation_anchor
        record = _ordered.__getitem__(holders, _tuple.__getitem__(_outcomes, index))
        tag = _tuple.__getitem__(record, 0)
        value = _tuple.__getitem__(record, 1)
        events = _object.__getattribute__(state, "events")
        if mode == "success":
            assert tag == "return"
            assert value is _object.__getattribute__(state, "final")
            assert events == success_events
        else:
            assert tag == "error"
            assert value is _object.__getattribute__(state, "marker")
            assert _type(value) is _base_exception
            assert value.args == ("t07-" + mode,)
            assert value.__traceback__ is not None
            assert value.__cause__ is None
            assert value.__context__ is None
            assert value.__suppress_context__ is False
            assert events == success_events[:success_events.index(mode) + 1]
        counts = _object.__getattribute__(state, "counts")
        expected_counts = {{
            "select": events.count("select"),
            "adapter": events.count("adapter"),
            "conversion": events.count("conversion"),
            "hook": events.count("hook"),
            "history-get": _sum(event.startswith("history-get-") for event in events),
            "jar-get": _sum(event.startswith("jar-get-") for event in events),
            "cookie": _sum(event.startswith("cookie-") for event in events),
            "redirect": events.count("redirect-create"),
            "redirect-iteration": _sum(
                event.startswith("redirect-iteration-") for event in events
            ),
        }}
        assert counts == expected_counts
        assert _all(count <= 2 for count in counts.values())
        rows.append((mode, tag, events, _snapshot(counts)))
    return rows


result = case_result("T07", v6_subject, {operation}, v6_controls, v6_observer)
