class V6R05Adapter:
    __slots__ = ("state", "responses")

    def __init__(self, state, responses):
        self.state = state
        self.responses = iter(tuple(responses))

    def send(self, request, **kwargs):
        response = self.state.next_call.value(self.responses)
        response.request = request
        response.url = request.url
        self.state.events.append(["adapter-send", response.name])
        return response


class V6R05SendAdapter(V6R05Adapter):
    __slots__ = ("label",)

    def __init__(self, state, responses, label):
        super().__init__(state, responses)
        self.label = label

    def send(self, request, **kwargs):
        self.state.events.append([
            "send", self.label, request.url,
            self.state.sort.value(kwargs),
            self.state.get_ident.value() == self.state.entry_thread,
        ])
        response = self.state.next_call.value(self.responses)
        response.request = request
        if response.url is None:
            response.url = request.url
        return response


