class V6R06Limit:
    __slots__ = ("state",)

    def __init__(self, state):
        self.state = state

    def __le__(self, count):
        self.state.events.append(["limit-compare", count])
        self.state._max = "message-mutated"
        return True


class V6R06Raw:
    __slots__ = ("state",)

    def __init__(self, state):
        self.state = state

    def read(self, *args, **kwargs):
        self.state.events.append([
            "fallback-read", list(args), list(kwargs.items())
        ])
        if self.state.mode == "fallback-error":
            raise self.state.fallback_marker
        return b""


class V6R06Response(Response):
    @property
    def content(self):
        state = self.v6_state
        module = state.module.value
        state.events.append("content")
        mode = state.mode
        if mode.startswith("catch-") or mode in (
            "first-match-third-invalid", "fallback-error"
        ):
            if mode in (
                "catch-matching", "first-match-third-invalid",
                "fallback-error",
            ):
                module.ChunkedEncodingError = state.content_type.value
            else:
                module.ChunkedEncodingError = state.key_error_type.value
            if mode == "catch-deleted":
                module.__dict__.pop("ContentDecodingError", None)
            elif mode in ("catch-invalid", "first-match-third-invalid"):
                module.RuntimeError = state.invalid_runtime
            else:
                module.RuntimeError = state.runtime_type.value
            raise state.content_marker
        return b""

    def close(self):
        self.v6_state.events.append("close")
        if self.v6_state.mode == "close-error":
            raise self.v6_state.marker


class V6R06Session(sessions_module.SessionRedirectMixin):
    trust_env = False

    def __init__(self, state):
        self.state = state
        self.cookies = RequestsCookieJar()

    @property
    def max_redirects(self):
        maximum = self.state._max
        if maximum is self.state.custom_limit:
            recorded = "custom"
        elif maximum is self.state.invalid_limit:
            recorded = "invalid"
        else:
            recorded = maximum
        self.state.events.append([
            "max-get", recorded,
        ])
        if self.state.mode == "max-error":
            raise self.state.marker
        return self.state._max

    def get_redirect_target(self, response):
        self.state.events.append("target")
        return "/next"

    def rebuild_method(self, prepared_request, response):
        self.state.events.append("method")

    def rebuild_proxies(self, prepared_request, proxies):
        self.state.events.append("proxy")
        return proxies

    def rebuild_auth(self, prepared_request, response):
        self.state.events.append("auth")


class V6R06TooMany:
    __slots__ = ("state",)

    def __init__(self, state):
        self.state = state

    def __call__(self, *args, **kwargs):
        self.state.events.append("too-many-call")
        raise self.state.marker


class V6R06Len:
    __slots__ = ("state", "original")

    def __init__(self, state):
        self.state = state
        self.original = AuthorityIdentity(v6_r06_original_len, "r06-original-len")

    def __call__(self, value):
        state = self.state
        state.events.append(["len", value.copy()])
        if state.mode == "len-error": raise state.marker
        return self.original.value(value)


