def _v6_without_legacy_runners(source: str) -> str:
    tree = ast.parse(source)
    retained = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and (
            node.name
            in {
                "oracle_call",
                "_original_oracle_call",
                "adversarial_oracle_call",
            }
            or node.name.endswith("_run")
        ):
            continue
        if isinstance(node, ast.Assign) and any(
            isinstance(target_node, ast.Name)
            and target_node.id == "_original_oracle_call"
            for target_node in node.targets
        ):
            continue
        retained.append(node)
    tree.body = retained
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)


def _assemble_v6_case(case_id: str, source: str, half_count: int) -> str:
    normalized = dedent(source)
    tree = ast.parse(normalized)
    result_node = next(
        node
        for node in reversed(tree.body)
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name) and target.id == "result"
            for target in node.targets
        )
    )
    assert isinstance(result_node.value, ast.Call)
    call = result_node.value
    assert isinstance(call.func, ast.Name) and call.func.id == "case_result"
    assert len(call.args) == 5
    lines = normalized.splitlines(keepends=True)
    prefix = "".join(lines[: result_node.lineno - 1]).rstrip()
    operation = ast.get_source_segment(normalized, call.args[2])
    oracle = ast.get_source_segment(normalized, call.args[4])
    assert operation is not None and oracle is not None
    token = secrets.token_hex(12)
    if case_id in {"T01", "T03", "T04", "T05", "T06", "T07", "T08"}:
        return dedent(_V6_CASE_SOURCES[case_id](token, operation))
    if case_id in _V6_CASE_SOURCES:
        prefix = _v6_without_legacy_runners(prefix)
        return dedent(prefix + "\n\n" + _V6_CASE_SOURCES[case_id](token, operation))
    halves = tuple("half-" + str(index) for index in range(half_count))
    final_source = f"""
{prefix}

v6_subject = build_scenario_bundle({token!r}, {operation}, {halves!r})
v6_controls = {{
    "schema": "phase-a-v6",
    "metadata": OrderedDict([
        ("version", 6),
        ("scenario_count", {half_count}),
    ]),
}}
v6_legacy_observer = {oracle}


def v6_observer(_subject):
    return v6_legacy_observer()


result = case_result(
    {case_id!r}, v6_subject, {operation}, v6_controls, v6_observer
)
"""
    return dedent(final_source)


for _case_id in tuple(_CASES):
    _CASES[_case_id] = _assemble_v6_case(
        _case_id,
        _CASES[_case_id],
        2 if _case_id in _CORRECTED_CASE_IDS else 1,
    )


_CASE_IDS = tuple(_CASES)


def _is_missing_session_trial(observations: dict[str, object]) -> bool:
    exception = observations["exception"]
    if not isinstance(exception, dict):
        return False
    mro = exception.get("mro")
    args = exception.get("args")
    return (
        isinstance(mro, list)
        and bool(mro)
        and mro[0] == {"module": "builtins", "name": "AttributeError"}
        and isinstance(args, list)
        and len(args) == 1
        and "_session_pipeline_trial" in str(args[0])
    )


