class MutationSpec:
    name: str
    case_id: str
    mode: str
    outcome: str
    path: str
    phase: str
    mutation_kind: str
    mutation_source: str
    expected_category: str

    def transform(self, source: str) -> str:
        assert source.count(_V6_MUTATION_INJECTION_ANCHOR) == 1
        conditional = (
            f"        if mode == {self.mode!r}:\n"
            + indent(dedent(self.mutation_source).strip(), "            ")
            + "\n"
        )
        return source.replace(
            _V6_MUTATION_INJECTION_ANCHOR,
            _V6_MUTATION_INJECTION_ANCHOR + conditional,
            1,
        )


def _environment_mode_outcomes(case_id: str) -> dict[str, str]:
    tree = ast.parse(_CASES[case_id])
    scenario_loop = next(
        node
        for node in tree.body
        if isinstance(node, ast.For)
        and isinstance(node.target, ast.Tuple)
        and [item.id for item in node.target.elts if isinstance(item, ast.Name)]
        == ["v6_index", "v6_mode"]
    )
    assert isinstance(scenario_loop.iter, ast.Call)
    assert isinstance(scenario_loop.iter.func, ast.Name)
    assert scenario_loop.iter.func.id == "enumerate"
    modes = ast.literal_eval(scenario_loop.iter.args[0])
    action = next(
        node
        for node in ast.walk(scenario_loop)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "Action"
        and any(keyword.arg == "outcome" for keyword in node.keywords)
    )
    outcome_node = next(
        keyword.value for keyword in action.keywords if keyword.arg == "outcome"
    )
    assert isinstance(outcome_node, ast.Subscript)
    outcomes = ast.literal_eval(outcome_node.value)
    assert len(modes) == len(outcomes)
    return dict(zip(modes, outcomes, strict=True))


def _environment_mutation_body(case_id: str, mode: str) -> tuple[str, str]:
    if case_id == "E01":
        if mode == "true":
            return (
                '_dict.__setitem__(proxies, "http", request_stream)',
                "proxies.http.value",
            )
        return (
            '_dict.__setitem__(proxies, "corrupt", proxy_value)',
            "proxies.empty." + mode,
        )
    if case_id == "E03":
        return (
            "_ordered.clear(proxy_result)",
            "proxy_result.topology." + mode,
        )
    if case_id == "E04":
        if mode == "proxy-before-ca-error":
            return "_dict.clear(proxies)", "proxies.partial.https"
        return (
            '_dict.__setitem__(proxies, "https", proxy_value)',
            "proxies.empty." + mode,
        )
    if case_id == "E05":
        fields = ("proxies", "stream", "verify", "cert")
        if mode == "ok":
            field_index = 0
            value_index = 6
        else:
            field_index = next(
                index
                for index, field in enumerate(fields)
                if mode.endswith("-" + field)
            )
            value_index = 5 if field_index == 0 else 6
            if field_index > 0:
                field_index = 0
        return (
            "session = _tuple.__getitem__(anchors, 1)\n"
            f"values = _tuple.__getitem__(anchors, {value_index})\n"
            f"_object.__setattr__(session, {fields[field_index]!r}, "
            f"_tuple.__getitem__(values, {field_index}))",
            "session." + fields[field_index] + "." + mode,
        )
    if case_id == "E06":
        retained = {
            "prepared-check",
            "headers-get",
            "url-get",
            "parse",
            "parsed-scheme",
            "trust-get",
            "resolve",
            "contains",
            "delete",
            "prepared-false",
        }
        if mode in retained or mode in {"ok", "auth-absent"}:
            return (
                "headers = _tuple.__getitem__(anchors, 3)\n_ordered.clear(headers)",
                "headers.expected-value." + mode,
            )
        return (
            "headers = _tuple.__getitem__(anchors, 3)\n"
            "old_value = _tuple.__getitem__(anchors, 17)\n"
            '_ordered.__setitem__(headers, "Proxy-Authorization", old_value)',
            "headers.expected-empty." + mode,
        )
    assert case_id == "E07"
    retained = {
        "rebuild-no-strip",
        "rebuild-false-prepared-first",
        "rebuild-false-prepared-second",
        "rebuild-stop-response-request",
        "rebuild-stop-prepared-first",
        "rebuild-stop-prepared-second",
        "rebuild-stop-headers",
        "rebuild-stop-original-url",
        "rebuild-stop-new-url",
    }
    if mode in retained:
        return (
            "headers = _tuple.__getitem__(anchors, 8)\n_ordered.clear(headers)",
            "headers.expected-old." + mode,
        )
    return (
        "headers = _tuple.__getitem__(anchors, 8)\n"
        "old_value = _tuple.__getitem__(anchors, 20)\n"
        '_ordered.__setitem__(headers, "Authorization", old_value)',
        "headers.expected-empty." + mode,
    )


