def _environment_mutation_specs() -> tuple[MutationSpec, ...]:
    specs = []
    for case_id, modes in _V6_MUTATION_MODES.items():
        mode_outcomes = _environment_mode_outcomes(case_id)
        for mode in modes:
            mutation_source, path = _environment_mutation_body(case_id, mode)
            name = _V6_SILENT_CORRUPTION_NAMES.get(
                (case_id, mode),
                case_id.lower() + "-" + mode + "-post-action-corruption",
            )
            specs.append(
                MutationSpec(
                    name=name,
                    case_id=case_id,
                    mode=mode,
                    outcome=mode_outcomes[mode],
                    path=path,
                    phase="pre-stub-oracle/post-stub-rewrite",
                    mutation_kind="post-action-corruption",
                    mutation_source=mutation_source,
                    expected_category="observer-assertion:nested-postcondition",
                )
            )
    positive_outcome = _environment_mode_outcomes("E06")["ok"]
    specs.append(
        MutationSpec(
            name="positive-unrelated-state",
            case_id="E06",
            mode="ok",
            outcome=positive_outcome,
            path="state.stage.unobserved",
            phase="pre-stub-oracle/post-stub-rewrite",
            mutation_kind="post-action-positive",
            mutation_source="_object.__setattr__(state, 'stage', 'unrelated')",
            expected_category="oracle-equal:unrelated-state",
        )
    )
    return tuple(specs)


