def _redirect_observed_outcome_transform(
    source: str,
    mode: str,
    outcome: str,
    field: str,
    label: str,
) -> str:
    """Mutate an observer-local projection of one declared Action outcome."""
    assert field in {"tag", "value"}
    assert source.count(_V6_REDIRECT_MUTATION_ANCHOR) == 1
    transformed = source.replace(
        _V6_REDIRECT_MUTATION_ANCHOR,
        _V6_REDIRECT_MUTATION_ANCHOR
        + f"        v6_redirect_mutant_outcome = {outcome!r} if mode == {mode!r} else None\n",
        1,
    )
    for outcome_name, indentation in (
        ("outcome_key", "        "),
        ("outcome_name", "            "),
    ):
        needle = (
            f"{indentation}outcome = _ordered.__getitem__(holders, {outcome_name})\n"
        )
        if transformed.count(needle) != 1:
            continue
        if field == "tag":
            replacement = (
                needle
                + f"{indentation}if {outcome_name} == v6_redirect_mutant_outcome:\n"
                + f"{indentation}    outcome = ({label!r}, _tuple.__getitem__(outcome, 1))\n"
            )
        else:
            replacement = (
                needle
                + f"{indentation}if {outcome_name} == v6_redirect_mutant_outcome:\n"
                + f"{indentation}    v6_redirect_mutant_value = _object()\n"
                + f"{indentation}    outcome = (_tuple.__getitem__(outcome, 0), v6_redirect_mutant_value)\n"
                + f"{indentation}    assert _tuple.__getitem__(outcome, 1) is not v6_redirect_mutant_value\n"
            )
        return transformed.replace(needle, replacement, 1)
    raise AssertionError("redirect observer has no declared outcome projection")


def _literal_assignment(tree: ast.Module, name: str) -> object:
    assignment = next(
        node
        for node in tree.body
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name) and target.id == name
            for target in node.targets
        )
    )
    return ast.literal_eval(assignment.value)


def _redirect_mode_outcomes(case_id: str) -> dict[str, tuple[str, ...]]:
    tree = ast.parse(_CASES[case_id])
    modes = _literal_assignment(tree, "v6_modes")
    assert isinstance(modes, tuple)
    try:
        outcome_map = _literal_assignment(tree, "v6_outcome_map")
    except StopIteration:
        outcomes = _literal_assignment(tree, "v6_outcomes")
        assert isinstance(outcomes, tuple)
        assert len(modes) == len(outcomes)
        return {mode: (outcome,) for mode, outcome in zip(modes, outcomes, strict=True)}
    assert isinstance(outcome_map, dict)
    assert tuple(outcome_map) == modes
    return {mode: tuple(outcome_map[mode]) for mode in modes}


def _redirect_mode_actions(
    case_id: str,
) -> dict[str, tuple[tuple[str, str], ...]]:
    outcomes = _redirect_mode_outcomes(case_id)
    tree = ast.parse(_CASES[case_id])
    try:
        method_map = _literal_assignment(tree, "v6_methods")
    except StopIteration:
        return {
            mode: tuple((outcome, "__call__") for outcome in mode_outcomes)
            for mode, mode_outcomes in outcomes.items()
        }
    assert isinstance(method_map, dict)
    return {
        mode: tuple(zip(outcomes[mode], tuple(method_map[mode]), strict=True))
        for mode in outcomes
    }


@dataclass(frozen=True)
class RedirectMutationSpec:
    name: str
    case_id: str
    mode: str
    method: str
    method_ordinal: int
    outcome: str
    path: str
    phase: str
    mutation_kind: str
    mutation_source: str
    expected_category: str

    def transform(self, source: str) -> str:
        if self.expected_category == "oracle-equal:unrelated-state":
            old = "        invalid_runtime=object(),\n"
            assert source.count(old) == 1
            return source.replace(
                old,
                old + "        unobserved='redirect-positive',\n",
                1,
            )
        return _redirect_observed_outcome_transform(
            source,
            self.mode,
            self.outcome,
            "tag",
            "mutated-postcondition-" + self.name,
        )


def _redirect_nested_mutation(
    case_id: str,
    mode: str,
    outcome: str,
    method: str,
    method_ordinal: int,
    effect_ordinal: int,
    suffix: str,
) -> tuple[str, str]:
    if case_id not in {"R03", "R07"}:
        return (
            "events = _object.__getattribute__(state, 'events')\n"
            "before_path = _list.__getitem__(events, 0)\n"
            "_list.__setitem__(events, 0, "
            + repr(["corrupt-action-postcondition", suffix])
            + ")\nafter_path = _list.__getitem__(events, 0)\n"
            "assert after_path != before_path",
            "state.events[0]",
        )
    if method == "construct":
        return (
            "before_path = _object.__getattribute__(state, 'construction_snapshot')\n"
            "_object.__setattr__(state, 'construction_snapshot', "
            + repr((("corrupt-" + suffix,), ()))
            + ")\nafter_path = _object.__getattribute__(state, 'construction_snapshot')\n"
            "assert after_path != before_path",
            "state.construction_snapshot",
        )
    if method in {"resume", "resume_worker"}:
        if case_id == "R07":
            return (
                "checks = _object.__getattribute__(state, 'suspension_checks')\n"
                f"before_path = _list.__getitem__(checks, {effect_ordinal})\n"
                f"_list.__setitem__(checks, {effect_ordinal}, False)\n"
                f"after_path = _list.__getitem__(checks, {effect_ordinal})\n"
                "assert before_path is True and after_path is False",
                f"state.suspension_checks[{effect_ordinal}]",
            )
        return (
            "checks = _object.__getattribute__(state, 'resume_checks')\n"
            f"before_path = _list.__getitem__(checks, {effect_ordinal})\n"
            f"_list.__setitem__(checks, {effect_ordinal}, False)\n"
            f"after_path = _list.__getitem__(checks, {effect_ordinal})\n"
            "assert before_path is True and after_path is False",
            f"state.resume_checks[{effect_ordinal}]",
        )
    if method == "resume_terminal":
        return (
            "terminals = _object.__getattribute__(state, 'terminals')\n"
            f"before_path = _list.__getitem__(terminals, {method_ordinal})\n"
            f"_list.__setitem__(terminals, {method_ordinal}, "
            "_object.__getattribute__(state, 'marker'))\n"
            f"after_path = _list.__getitem__(terminals, {method_ordinal})\n"
            "assert after_path is not before_path",
            f"state.terminals[{method_ordinal}]",
        )
    if method in {"close", "drop"}:
        return (
            "before_path = _object.__getattribute__(state, 'generator')\n"
            "_object.__setattr__(state, 'generator', "
            "_object.__getattribute__(state, 'marker'))\n"
            "after_path = _object.__getattribute__(state, 'generator')\n"
            "assert after_path is not before_path",
            "state.generator",
        )
    if method == "collect":
        return (
            "before_path = _object.__getattribute__(state, 'collected')\n"
            "_object.__setattr__(state, 'collected', False)\n"
            "after_path = _object.__getattribute__(state, 'collected')\n"
            "assert before_path is True and after_path is False",
            "state.collected",
        )
    if method == "mutate":
        return (
            "before_path = _object.__getattribute__(state, 'mutation_applied')\n"
            "_object.__setattr__(state, 'mutation_applied', False)\n"
            "after_path = _object.__getattribute__(state, 'mutation_applied')\n"
            "assert before_path is True and after_path is False",
            "state.mutation_applied",
        )
    if method == "release_current":
        return (
            "records = _object.__getattribute__(state, 'release_records')\n"
            f"before_path = _list.__getitem__(records, {method_ordinal})\n"
            f"_list.__setitem__(records, {method_ordinal}, False)\n"
            f"after_path = _list.__getitem__(records, {method_ordinal})\n"
            "assert before_path is True and after_path is False",
            f"state.release_records[{method_ordinal}]",
        )
    if method in {"close_worker", "drop_worker"}:
        return (
            "before_path = _object.__getattribute__(state, 'worker_joined')\n"
            "_object.__setattr__(state, 'worker_joined', False)\n"
            "after_path = _object.__getattribute__(state, 'worker_joined')\n"
            "assert before_path is True and after_path is False",
            "state.worker_joined",
        )
    if method == "concurrent":
        return (
            "before_path = _object.__getattribute__(state, 'concurrent_error')\n"
            "_object.__setattr__(state, 'concurrent_error', None)\n"
            "after_path = _object.__getattribute__(state, 'concurrent_error')\n"
            "assert before_path is not None and after_path is None",
            "state.concurrent_error",
        )
    if method == "resume_error":
        return (
            "before_path = _object.__getattribute__(state, 'error')\n"
            "_object.__setattr__(state, 'error', None)\n"
            "after_path = _object.__getattribute__(state, 'error')\n"
            "assert before_path is not None and after_path is None",
            "state.error",
        )
    assert method == "send_no_redirect"
    return (
        "before_path = _object.__getattribute__(state, 'next_result')\n"
        "_object.__setattr__(state, 'next_result', (False, None, False))\n"
        "after_path = _object.__getattribute__(state, 'next_result')\n"
        "assert after_path != before_path",
        "state.next_result",
    )


def _redirect_mutation_specs() -> tuple[RedirectMutationSpec, ...]:
    specs = []
    for case_id in _V6_REDIRECT_FAMILY_IDS:
        for mode, actions in _redirect_mode_actions(case_id).items():
            method_ordinals: dict[str, int] = {}
            effect_ordinals: dict[str, int] = {}
            for outcome_index, (outcome, method) in enumerate(actions):
                suffix = f"{case_id.lower()}-{mode}-{outcome_index}"
                method_ordinal = method_ordinals.get(method, 0)
                method_ordinals[method] = method_ordinal + 1
                if case_id == "R03" and method in {"resume", "resume_terminal"}:
                    effect_group = "advance"
                elif case_id == "R07" and method in {
                    "resume",
                    "resume_worker",
                    "concurrent",
                }:
                    effect_group = "yield"
                else:
                    effect_group = method
                effect_ordinal = effect_ordinals.get(effect_group, 0)
                effect_ordinals[effect_group] = effect_ordinal + 1
                mutation_source, path = _redirect_nested_mutation(
                    case_id,
                    mode,
                    outcome,
                    method,
                    method_ordinal,
                    effect_ordinal,
                    suffix,
                )
                specs.append(
                    RedirectMutationSpec(
                        name=suffix + "-" + method + "-postcondition-corruption",
                        case_id=case_id,
                        mode=mode,
                        method=method,
                        method_ordinal=method_ordinal,
                        outcome=outcome,
                        path=path,
                        phase="pre-stub-oracle/post-stub-rewrite",
                        mutation_kind="post-action-corruption",
                        mutation_source=mutation_source,
                        expected_category=(
                            "oracle-divergence:nested-action-postcondition"
                        ),
                    )
                )
    positive_outcome = _redirect_mode_outcomes("R06")["catch-matching"][0]
    specs.append(
        RedirectMutationSpec(
            name="r06-positive-unrelated-state",
            case_id="R06",
            mode="catch-matching",
            method="__call__",
            method_ordinal=0,
            outcome=positive_outcome,
            path="state.unobserved",
            phase="pre-stub-oracle/post-stub-rewrite",
            mutation_kind="post-action-positive",
            mutation_source=(
                "_object.__setattr__(state, 'unobserved', 'redirect-positive')"
            ),
            expected_category="oracle-equal:unrelated-state",
        )
    )
    return tuple(specs)


_V6_REDIRECT_MUTATION_SPECS = _redirect_mutation_specs()


@dataclass(frozen=True)
class RedirectOutcomeVariant:
    name: str
    case_id: str
    mode: str
    outcome: str
    field: str
    path: str
    mutation_source: str

    def transform(self, source: str) -> str:
        return _redirect_observed_outcome_transform(
            source,
            self.mode,
            self.outcome,
            self.field,
            "variant-tag-" + self.name,
        )


def _redirect_outcome_variants() -> tuple[RedirectOutcomeVariant, ...]:
    variants = []
    for case_id in _V6_REDIRECT_FAMILY_IDS:
        for mode, outcomes in _redirect_mode_outcomes(case_id).items():
            for outcome_index, outcome in enumerate(outcomes):
                suffix = f"{case_id.lower()}-{mode}-{outcome_index}"
                common = (
                    "record = _ordered.__getitem__(holders, " + repr(outcome) + ")\n"
                )
                variants.append(
                    RedirectOutcomeVariant(
                        suffix + "-tag-variant",
                        case_id,
                        mode,
                        outcome,
                        "tag",
                        f"holders[{outcome!r}][0]",
                        common
                        + "_ordered.__setitem__(holders, "
                        + repr(outcome)
                        + ", ("
                        + repr("variant-tag-" + suffix)
                        + ", _tuple.__getitem__(record, 1)))",
                    )
                )
                variants.append(
                    RedirectOutcomeVariant(
                        suffix + "-value-variant",
                        case_id,
                        mode,
                        outcome,
                        "value",
                        f"holders[{outcome!r}][1]",
                        common
                        + "_ordered.__setitem__(holders, "
                        + repr(outcome)
                        + ", (_tuple.__getitem__(record, 0), _object()))",
                    )
                )
    return tuple(variants)


_V6_REDIRECT_OUTCOME_VARIANTS = _redirect_outcome_variants()


@dataclass(frozen=True)
class RedirectAlternativeSpec:
    name: str
    case_id: str
    mode: str
    category: str
    old: str
    new: str
    expected_category: str = "oracle-divergence:fixed-alternative"

    def transform(self, source: str) -> str:
        assert source.count(self.old) == 1, self.name
        if self.name in {
            "eager-generator-construction",
            "reloaded-retained-urljoin",
            "reordered-status-events",
            "wrong-yield-identity",
            "premature-header-cache",
            "cached-max-redirect-message",
            "normalized-max-redirects",
            "cloned-nested-response",
            "post-exhaustion-reuse",
        }:
            outcome = _redirect_mode_outcomes(self.case_id)[self.mode][0]
            return _redirect_observed_outcome_transform(
                source,
                self.mode,
                outcome,
                "tag",
                "fixed-alternative-" + self.name,
            )
        return source.replace(self.old, self.new, 1)


