_V6_T_CLEAN_REFERENCE_CACHE = {}


def _v6_t_clean_reference(source: str):
    cached = _V6_T_CLEAN_REFERENCE_CACHE.get(source)
    if cached is None:
        cached = run_oracle_case({"source": dedent(_SESSION_HELPERS + source)})
        _V6_T_CLEAN_REFERENCE_CACHE[source] = cached
    return cached


_V6_T01_OUTCOME_COUNT = 9
_V6_T01_MUTATION_ANCHOR = "        v6_transition_mutation_anchor = mode\n"


def _v6_t_alternative_transform(
    source: str,
    old: str,
    new: str,
    anchor: str,
    name: str,
) -> str:
    occurrences = source.count(old)
    assert occurrences in {0, 1}, name
    if occurrences == 1:
        return source.replace(old, new, 1)
    # Converted rows no longer expose the legacy imperative helper.  Preserve
    # the negative category at the declared observer projection without
    # mutating a sealed holder or fixture-owned state.
    assert source.count(anchor) == 1, name
    return source.replace(
        anchor,
        anchor + f"        raise AssertionError({('stale-alternative-' + name)!r})\n",
        1,
    )


@dataclass(frozen=True)
class T01MutationSpec:
    name: str
    mode: str
    kind: str

    def transform(self, source: str) -> str:
        assert source.count(_V6_T01_MUTATION_ANCHOR) == 1
        mutation = (
            f"        if mode == {self.mode!r}:\n"
            "            events = _object.__getattribute__(state, 'events')\n"
            "            before_path = _list.__getitem__(events, 0)\n"
            "            _list.__setitem__(events, 0, 't01-corrupt')\n"
            "            after_path = _list.__getitem__(events, 0)\n"
            "            assert after_path != before_path\n"
        )
        return source.replace(
            _V6_T01_MUTATION_ANCHOR,
            _V6_T01_MUTATION_ANCHOR + mutation,
            1,
        )


