@dataclass(frozen=True)
class T01OutcomeVariant:
    name: str
    mode: str
    outcome: str
    field: str

    def transform(self, source: str) -> str:
        mutation = (
            f"        if mode == {self.mode!r}:\n"
            f"            record = _ordered.__getitem__(holders, {self.outcome!r})\n"
        )
        if self.field == "tag":
            mutation += (
                f"            _ordered.__setitem__(holders, {self.outcome!r}, "
                "('variant-tag', _tuple.__getitem__(record, 1)))\n"
            )
        else:
            mutation += (
                f"            _ordered.__setitem__(holders, {self.outcome!r}, "
                "(_tuple.__getitem__(record, 0), _object()))\n"
            )
        return source.replace(
            _V6_T01_MUTATION_ANCHOR,
            _V6_T01_MUTATION_ANCHOR + mutation,
            1,
        )


def _v6_t01_outcome_variants() -> tuple[T01OutcomeVariant, ...]:
    outcomes = _literal_assignment(ast.parse(_CASES["T01"]), "v6_outcomes")
    assert isinstance(outcomes, tuple)
    return tuple(
        T01OutcomeVariant(
            "t01-" + mode + "-" + field,
            mode,
            outcome,
            field,
        )
        for mode, outcome in zip(_V6_T01_MODES, outcomes, strict=True)
        for field in ("tag", "value")
    )


_V6_T01_OUTCOME_VARIANTS = _v6_t01_outcome_variants()


def _assert_v6_t_semantic_action_graph(
    case_id: str,
    root_attribute: str,
    *,
    generator: bool,
) -> None:
    source = _CASES[case_id]
    tree = ast.parse(source)
    action_calls = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "Action"
    ]
    assert action_calls
    assert any(
        isinstance(call.args[0], ast.Constant) and call.args[0].value == "semantic-call"
        for call in action_calls
    )
    native_roots = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "native_operation"
        and len(node.args) >= 2
        and isinstance(node.args[1], ast.Constant)
    ]
    assert any(node.args[1].value == root_attribute for node in native_roots)
    assert any(
        isinstance(call.args[0], ast.Constant) and call.args[0].value == "native-call"
        for call in action_calls
    )
    assert any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "register_semantic_patch"
        and node.args
        and isinstance(node.args[0], ast.Call)
        and isinstance(node.args[0].func, ast.Name)
        and node.args[0].func.id == "Patch"
        for node in ast.walk(tree)
    )
    assert source.count("result = case_result(") == 1
    for forbidden in (
        "Invocation",
        "state.completed is False",
        "def oracle_call",
        "def adversarial_oracle_call",
        "_v6_private_resolve",
    ):
        assert forbidden not in source
    if generator:
        assert "GeneratorHandle(" in source
        assert "GeneratorOutcomeInstaller()" in source
        assert any(
            isinstance(call.args[0], ast.Constant)
            and call.args[0].value in {"next", "close"}
            for call in action_calls
        )


