_V6_T05_OUTCOME_COUNT = len(_V6_T05_MODES)
_V6_T05_MUTATION_ANCHOR = "        v6_transition_mutation_anchor = mode\n"


@dataclass(frozen=True)
class T05MutationSpec:
    name: str
    mode: str
    kind: str

    def transform(self, source: str) -> str:
        assert source.count(_V6_T05_MUTATION_ANCHOR) == 1
        mutation = (
            f"        if mode == {self.mode!r}:\n"
            "            live_events = _object.__getattribute__(state, 'events')\n"
            "            before_path = _list.__getitem__(live_events, 0)\n"
            "            _list.__setitem__(live_events, 0, ('t05-corrupt',))\n"
            "            after_path = _list.__getitem__(live_events, 0)\n"
            "            assert after_path != before_path\n"
        )
        return source.replace(
            _V6_T05_MUTATION_ANCHOR,
            _V6_T05_MUTATION_ANCHOR + mutation,
            1,
        )


_V6_T05_MUTATIONS = tuple(
    T05MutationSpec("t05-" + mode + "-action", mode, "negative")
    for mode in _V6_T05_MODES
) + (T05MutationSpec("t05-positive-unrelated", "digest-first", "positive"),)


@dataclass(frozen=True)
class T05OutcomeVariant:
    name: str
    mode: str
    outcome: str
    field: str

    def transform(self, source: str) -> str:
        mutation = (
            f"        if mode == {self.mode!r}:\n"
            f"            varied = _ordered.__getitem__(holders, {self.outcome!r})\n"
        )
        if self.field == "tag":
            mutation += (
                f"            _ordered.__setitem__(holders, {self.outcome!r}, "
                "('variant-tag', _tuple.__getitem__(varied, 1)))\n"
            )
        else:
            mutation += (
                f"            _ordered.__setitem__(holders, {self.outcome!r}, "
                "(_tuple.__getitem__(varied, 0), _object()))\n"
            )
        assert source.count(_V6_T05_MUTATION_ANCHOR) == 1
        return source.replace(
            _V6_T05_MUTATION_ANCHOR,
            _V6_T05_MUTATION_ANCHOR + mutation,
            1,
        )


def _v6_t05_outcome_variants() -> tuple[T05OutcomeVariant, ...]:
    outcomes = _literal_assignment(ast.parse(_CASES["T05"]), "v6_outcomes")
    assert isinstance(outcomes, tuple)
    return tuple(
        T05OutcomeVariant("t05-" + mode + "-" + field, mode, outcome, field)
        for mode, outcome in zip(_V6_T05_MODES, outcomes, strict=True)
        for field in ("tag", "value")
    )


