def test_v6_t05_observer_is_closed_and_inspection_only() -> None:
    source = _CASES["T05"]
    table = symtable.symtable(source, "<t05-observer>", "exec")
    observer_table = next(
        child for child in table.get_children() if child.get_name() == "v6_observer"
    )
    assert [
        symbol.get_name()
        for symbol in observer_table.get_symbols()
        if symbol.is_global() and symbol.is_referenced()
    ] == []
    observer = next(
        node
        for node in ast.parse(source).body
        if isinstance(node, ast.FunctionDef) and node.name == "v6_observer"
    )
    observer_source = ast.unparse(observer)
    for forbidden in (
        "Session",
        "SessionRedirectMixin",
        "Driver",
        "Invocation",
        "case_result",
        "oracle_call",
        "_session_pipeline_trial",
    ):
        assert forbidden not in observer_source
    assert not any(
        isinstance(node, (ast.Yield, ast.YieldFrom, ast.Await))
        for node in ast.walk(observer)
    )


