@dataclass(frozen=True)
class T08MutationSpec:
    name: str
    mode: str
    kind: str

    def transform(self, source: str) -> str:
        mutation = (
            f"        if mode == {self.mode!r}:\n"
            "            live_events = _object.__getattribute__(state, 'events')\n"
            "            before_path = _list.__getitem__(live_events, 0)\n"
            "            _list.__setitem__(live_events, 0, ('t08-corrupt',))\n"
            "            after_path = _list.__getitem__(live_events, 0)\n"
            "            assert after_path != before_path\n"
        )
        assert source.count(_V6_T08_MUTATION_ANCHOR) == 1
        return source.replace(
            _V6_T08_MUTATION_ANCHOR,
            _V6_T08_MUTATION_ANCHOR + mutation,
            1,
        )


_V6_T08_MUTATIONS = tuple(
    T08MutationSpec("t08-" + mode + "-action", mode, "negative")
    for mode in _V6_T08_MODES
) + (T08MutationSpec("t08-positive-unrelated", "success", "positive"),)


@dataclass(frozen=True)
class T08OutcomeVariant:
    name: str
    mode: str
    outcome: str
    field: str

    def transform(self, source: str) -> str:
        mutation = (
            f"        if mode == {self.mode!r}:\n"
            f"            varied = _ordered.__getitem__(holders, {self.outcome!r})\n"
        )
        if self.field == "tag":
            mutation += (
                f"            _ordered.__setitem__(holders, {self.outcome!r}, "
                "('variant-tag', _tuple.__getitem__(varied, 1)))\n"
            )
        else:
            mutation += (
                f"            _ordered.__setitem__(holders, {self.outcome!r}, "
                "(_tuple.__getitem__(varied, 0), _object()))\n"
            )
        return source.replace(
            _V6_T08_MUTATION_ANCHOR,
            _V6_T08_MUTATION_ANCHOR + mutation,
            1,
        )


