@pytest.mark.parametrize("case_id", _V6_ENVIRONMENT_FAMILY_IDS)
def test_v6_environment_observer_sources_are_inspection_only(
    case_id: str,
) -> None:
    tree = ast.parse(_CASES[case_id])
    observer = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name == "v6_observer"
    )
    source = ast.unparse(observer)
    assert "observables = _object.__getattribute__(context, 'observables')" in (source)
    assert "anchors = _ordered.__getitem__(observables, 'anchors')" in source

    forbidden_names = {
        "all",
        "any",
        "dict",
        "enumerate",
        "iter",
        "list",
        "next",
        "tuple",
        "zip",
    }
    forbidden_methods = {"__iter__", "get", "items", "startswith"}
    calls = [node for node in ast.walk(observer) if isinstance(node, ast.Call)]
    assert [
        node
        for node in calls
        if isinstance(node.func, ast.Name) and node.func.id in forbidden_names
    ] == []
    assert [
        node
        for node in calls
        if isinstance(node.func, ast.Attribute) and node.func.attr in forbidden_methods
    ] == []

    bound_getitem_owners = {"_dict", "_list", "_ordered", "_tuple"}
    getitem_calls = [
        node
        for node in calls
        if isinstance(node.func, ast.Attribute) and node.func.attr == "__getitem__"
    ]
    assert getitem_calls
    assert all(
        isinstance(node.func.value, ast.Name)
        and node.func.value.id in bound_getitem_owners
        for node in getitem_calls
    )

    candidate_names = {
        "anchors",
        "context",
        "holders",
        "observables",
        "proxies",
        "request",
        "state",
        "subject",
        "value",
    }
    assert [
        node
        for node in ast.walk(observer)
        if isinstance(node, ast.Subscript)
        and isinstance(node.value, ast.Name)
        and node.value.id in candidate_names
    ] == []


def test_v6_inspection_helpers_bind_exact_builtin_operations() -> None:
    tree = ast.parse(_SESSION_HELPERS)
    helper_names = {
        "inspection_snapshot",
        "inspection_mapping_items",
        "inspection_base_mapping_items",
    }
    helpers = [
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name in helper_names
    ]
    assert {node.name for node in helpers} == helper_names
    source = "\n".join(ast.unparse(node) for node in helpers)
    assert "type(value)" in source
    assert "list.__iter__(value)" in source
    assert "tuple.__iter__(value)" in source
    assert "dict.items(value)" in source
    assert "OrderedDict.items(value)" in source
    assert "getattr(" not in source
    assert "iter(" not in source
    assert ".items()" not in source


