@pytest.mark.parametrize("case_id", _V6_ENVIRONMENT_FAMILY_IDS)
def test_v6_environment_runtime_guard_rejects_semantic_replay(
    case_id: str,
) -> None:
    needle = "        rows.append({\n"
    replay = (
        "        replay_receiver = _object.__getattribute__(\n"
        '            scenario, "receiver"\n'
        "        )\n"
        '        _object.__getattribute__(replay_receiver, "__call__")()\n'
    )
    source = _CASES[case_id]
    assert source.count(needle) == 1
    mutant = source.replace(needle, replay + needle, 1)
    oracle = run_oracle_case({"source": dedent(_SESSION_HELPERS + mutant)})
    exception = oracle.observations["exception"]
    assert isinstance(exception, dict)
    assert exception["mro"][0]["name"] == "AssertionError"
    assert exception["args"] == [f"{case_id} semantic operation replayed"]


