def _mutation_free_names(mutation_source: str) -> set[str]:
    wrapper = (
        "def mutation("
        + ", ".join(_V6_MUTATION_INTERFACE)
        + "):\n"
        + indent(dedent(mutation_source).strip(), "    ")
        + "\n"
    )
    module_table = symtable.symtable(wrapper, "<mutation-spec>", "exec")
    function_table = module_table.get_children()[0]
    return {
        symbol.get_name()
        for symbol in function_table.get_symbols()
        if symbol.is_global() and symbol.is_referenced()
    }


def test_v6_environment_mutation_spec_inventory_is_executable() -> None:
    specs = _V6_ENVIRONMENT_MUTATION_SPECS
    negatives = [
        spec
        for spec in specs
        if spec.expected_category == "observer-assertion:nested-postcondition"
    ]
    positives = [
        spec
        for spec in specs
        if spec.expected_category == "oracle-equal:unrelated-state"
    ]
    assert len(specs) == 77
    assert len(negatives) == 76
    assert len(positives) == 1
    assert len({spec.name for spec in specs}) == 77
    assert (
        len({(spec.case_id, spec.mode, spec.outcome, spec.path) for spec in specs})
        == 77
    )
    assert {spec.name for spec in specs if spec.name.startswith("silent-")} == set(
        _V6_SILENT_CORRUPTION_NAMES.values()
    )
    assert sum(_V6_ENVIRONMENT_OUTCOME_COUNTS.values()) == 119

    for spec in specs:
        assert spec.case_id in _V6_ENVIRONMENT_FAMILY_IDS
        assert spec.outcome == _environment_mode_outcomes(spec.case_id)[spec.mode]
        assert spec.path
        assert spec.phase == "pre-stub-oracle/post-stub-rewrite"
        assert spec.mutation_kind in {
            "post-action-corruption",
            "post-action-positive",
        }
        assert _mutation_free_names(spec.mutation_source) == set()
        source = _CASES[spec.case_id]
        mutated = spec.transform(source)
        assert mutated == spec.transform(source)
        assert mutated != source
        compile(
            dedent(_SESSION_HELPERS + mutated),
            "<environment-mutation-spec>",
            "exec",
        )


