def _redirect_path_is_traversable(path: str) -> bool:
    expression = ast.parse(path, mode="eval").body
    while isinstance(expression, (ast.Attribute, ast.Subscript)):
        if isinstance(expression, ast.Subscript):
            assert isinstance(expression.slice, ast.Constant)
            assert isinstance(expression.slice.value, (int, str))
        expression = expression.value
    return isinstance(expression, ast.Name) and expression.id in {"state", "holders"}


def test_v6_redirect_mutation_spec_inventory_is_action_specific() -> None:
    specs = _V6_REDIRECT_MUTATION_SPECS
    negatives = [
        spec
        for spec in specs
        if spec.expected_category == "oracle-divergence:nested-action-postcondition"
    ]
    positives = [
        spec
        for spec in specs
        if spec.expected_category == "oracle-equal:unrelated-state"
    ]
    assert len(specs) == 135
    assert len(negatives) == 134
    assert len(positives) == 1
    assert len({spec.name for spec in specs}) == 135
    assert (
        len(
            {
                (
                    spec.case_id,
                    spec.mode,
                    spec.method,
                    spec.method_ordinal,
                    spec.path,
                )
                for spec in specs
            }
        )
        == 135
    )
    assert {
        case_id: sum(spec.case_id == case_id for spec in negatives)
        for case_id in _V6_REDIRECT_FAMILY_IDS
    } == _V6_REDIRECT_OUTCOME_COUNTS

    for spec in specs:
        action_rows = _redirect_mode_actions(spec.case_id)[spec.mode]
        actions = dict(action_rows)
        assert actions[spec.outcome] == spec.method
        action_index = next(
            index
            for index, (outcome, _) in enumerate(action_rows)
            if outcome == spec.outcome
        )
        assert spec.method_ordinal == sum(
            method == spec.method for _, method in action_rows[:action_index]
        )
        assert _redirect_path_is_traversable(spec.path)
        assert spec.phase == "pre-stub-oracle/post-stub-rewrite"
        assert _mutation_free_names(spec.mutation_source) == set()
        if spec in negatives:
            mutation_tree = ast.parse(spec.mutation_source)
            assigned_names = {
                target.id
                for node in ast.walk(mutation_tree)
                if isinstance(node, ast.Assign)
                for target in node.targets
                if isinstance(target, ast.Name)
            }
            assert {"before_path", "after_path"}.issubset(assigned_names)
            assert any(
                isinstance(node, ast.Assert)
                and {"before_path", "after_path"}.issubset(
                    {
                        child.id
                        for child in ast.walk(node.test)
                        if isinstance(child, ast.Name)
                    }
                )
                for node in ast.walk(mutation_tree)
            )
        source = _CASES[spec.case_id]
        mutated = spec.transform(source)
        assert mutated == spec.transform(source)
        assert mutated != source
        compile(dedent(_SESSION_HELPERS + mutated), "<redirect-mutation>", "exec")


