@pytest.mark.parametrize("case_id", _V6_REDIRECT_FAMILY_IDS)
def test_v6_redirect_observers_are_anchored_and_inspection_only(
    case_id: str,
) -> None:
    observer = next(
        node
        for node in ast.parse(_CASES[case_id]).body
        if isinstance(node, ast.FunctionDef) and node.name == "v6_observer"
    )
    source = ast.unparse(observer)
    assert "observables = _object.__getattribute__(context, 'observables')" in source
    assert "anchors = _ordered.__getitem__(observables, 'anchors')" in source
    assert "v6_redirect_mutation_anchor = mode" in source
    assert "oracle_call" not in source
    assert "_session_pipeline_trial" not in source
    assert [
        node
        for node in ast.walk(observer)
        if isinstance(node, (ast.Yield, ast.YieldFrom, ast.Await))
    ] == []
    forbidden_names = {"next"}
    forbidden_methods = {
        "close",
        "collect",
        "get_redirect_target",
        "join",
        "rebuild_auth",
        "rebuild_method",
        "rebuild_proxies",
        "resolve_redirects",
        "send",
        "start",
    }
    calls = [node for node in ast.walk(observer) if isinstance(node, ast.Call)]
    assert [
        node
        for node in calls
        if isinstance(node.func, ast.Name) and node.func.id in forbidden_names
    ] == []
    assert [
        node
        for node in calls
        if isinstance(node.func, ast.Attribute) and node.func.attr in forbidden_methods
    ] == []
    assert [
        target
        for node in ast.walk(observer)
        if isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign))
        for target in (node.targets if isinstance(node, ast.Assign) else (node.target,))
        if isinstance(target, (ast.Attribute, ast.Subscript))
    ] == []


