def test_v6_redirect_generator_handles_are_preconstructed_anchored_and_exact() -> None:
    installer_methods = [
        call.args[2].value
        for case_id in ("T01", "T02", "T03", "T04", "R03", "R04", "R05", "R06", "R07")
        for call in ast.walk(ast.parse(_CASES[case_id]))
        if isinstance(call, ast.Call)
        and isinstance(call.func, ast.Name)
        and call.func.id == "Action"
        and len(call.args) >= 3
        and isinstance(call.args[1], ast.Name)
        and call.args[1].id in {"v6_installer", "v6_installer_identity"}
        and isinstance(call.args[2], ast.Constant)
    ]
    assert installer_methods == ["install_generator"] * 9

    handle_class = next(
        node
        for node in ast.parse(_SESSION_HELPERS).body
        if isinstance(node, ast.ClassDef) and node.name == "GeneratorHandle"
    )
    handle_source = ast.unparse(handle_class)
    assert "_TERMINAL_STOP" not in handle_source
    assert "_stop_iteration" not in handle_source
    assert not any(
        isinstance(node, ast.Name) and node.id == "StopIteration"
        for node in ast.walk(handle_class)
    )
    for case_id in ("R03", "R07"):
        source = _CASES[case_id]
        assert 'v6_state.handle = GeneratorHandle(object(), "r0' in source
        assert "v6_state.handle," in source
        assert "is handle" in source
        assert '"registered") is False' in source

    probe = run_oracle_case(
        {
            "source": dedent(
                _SESSION_HELPERS
                + r"""
handle = GeneratorHandle(object(), "registered")
clone = GeneratorHandle(object(), "clone")
same_token_clone = GeneratorHandle(handle.token, "same-token-clone")
duplicate = GeneratorHandle(handle.token, "duplicate-install")

def values():
    yield "value"

handle.install(values())
try:
    duplicate.install(values())
except KeyError:
    duplicate_install_rejected = True
else:
    duplicate_install_rejected = False
try:
    next(clone)
except KeyError:
    clone_rejected = True
else:
    clone_rejected = False
for operation in ("next", "close", "drop", "registered", "gi_frame"):
    try:
        if operation == "next":
            next(same_token_clone)
        elif operation == "close":
            same_token_clone.close()
        elif operation == "drop":
            same_token_clone.drop()
        elif operation == "registered":
            same_token_clone.registered
        else:
            same_token_clone.gi_frame
    except KeyError:
        pass
    else:
        raise AssertionError("same-token clone accessed generator: " + operation)
assert next(handle) == "value"
terminal_records = []
try:
    next(handle)
except StopIteration as first_terminal:
    assert type(first_terminal) is StopIteration
    assert first_terminal.__traceback__ is not None
    assert first_terminal.__context__ is None
    assert first_terminal.__cause__ is None
    assert first_terminal.__suppress_context__ is False
    terminal_records.append(first_terminal)
else:
    raise AssertionError("generator handle did not terminate")
try:
    next(handle)
except StopIteration as second_terminal:
    assert type(second_terminal) is StopIteration
    assert second_terminal is not terminal_records[0]
    assert second_terminal.__traceback__ is not None
    assert second_terminal.__context__ is None
    assert second_terminal.__cause__ is None
    assert second_terminal.__suppress_context__ is False
    terminal_records.append(second_terminal)
else:
    raise AssertionError("exhausted generator handle did not terminate")
try:
    duplicate.install(values())
except KeyError:
    terminated_install_rejected = True
else:
    terminated_install_rejected = False
for operation in ("next", "close", "drop", "registered", "gi_frame"):
    try:
        if operation == "next":
            next(same_token_clone)
        elif operation == "close":
            same_token_clone.close()
        elif operation == "drop":
            same_token_clone.drop()
        elif operation == "registered":
            same_token_clone.registered
        else:
            same_token_clone.gi_frame
    except KeyError:
        pass
    else:
        raise AssertionError(
            "same-token clone accessed terminated generator: " + operation
        )
assert handle.gi_frame is None
assert handle.registered is True
handle.close()
assert handle.registered is False
assert _GENERATOR_REGISTRY == {} and _TERMINATED_GENERATORS == {}
result = (
    clone_rejected and duplicate_install_rejected
    and terminated_install_rejected
)
"""
            )
        }
    )
    assert probe.observations["exception"] is None
    assert probe.observations["result"]["repr"] == "True"
    assert probe.stderr == ""


