class SemanticError:
    __slots__ = ("error",)
    def __init__(self, error): self.error = error
    def __call__(self): raise self.error

cause = ValueError("cause")
chained = LookupError("context")
marker = BaseException("semantic")
marker.__cause__ = cause
marker.__context__ = chained
marker.__suppress_context__ = True
context = ScenarioContext(
    "semantic-error", markers=(marker, cause, chained), mutations=()
)
