def _replacement_root_case_source(case_id: str) -> str:
    if case_id == "R01":
        method = "get_redirect_target"
        operation = "redirect-target"
        bound_body = "self.context.events.append('bound'); return 'bound'"
        instance_body = "self.context.events.append('instance'); return 'instance'"
        class_body = (
            "assert _type(self).__dict__['get_redirect_target'] is self.expected.value; "
            "self.context.events.append('class'); return 'class'"
        )
        bound_args = "(response,)"
        class_args = "(class_session, response)"
        result_expr = "value"
        setup = "response = object()"
    else:
        method = "rebuild_method"
        operation = "redirect-method"
        bound_body = "self.context.events.append('bound'); request.method = 'BOUND'"
        instance_body = (
            "self.context.events.append('instance'); request.method = 'INSTANCE'"
        )
        class_body = (
            "assert _type(self).__dict__['rebuild_method'] is self.expected.value; "
            "self.context.events.append('class'); request.method = 'CLASS'"
        )
        bound_args = "(request, response)"
        class_args = "(class_session, request, response)"
        result_expr = "anchors[0].method"
        setup = "request = SimpleNamespace(method='POST')\nresponse = object()"
    return f"""
class BoundSession(sessions_module.SessionRedirectMixin):
    def __init__(self, context): self.context = context
    def {method}(self, request, response=None): {bound_body}

class InstanceReplacement:
    __slots__ = ("context",)
    def __init__(self, context): self.context = context
    def __call__(self, request, response=None): {instance_body}

def class_replacement(self, request, response=None, _type=type):
    {class_body}

{setup}
scenarios = []
for index, mode in enumerate(("bound", "instance", "class")):
    context = ScenarioContext(
        "replacement-" + mode,
        observables=OrderedDict((("anchors", ((request,) if {case_id!r} == "R02" else ())),)),
        mutations=("events",),
    )
    patches = ()
    if mode == "bound":
        session = BoundSession(context)
        entry = AuthorityIdentity(getattr(session, {method!r}), "bound-root")
        args = {bound_args}
    elif mode == "instance":
        replacement = InstanceReplacement(context)
        session = SimpleNamespace(**{{{method!r}: replacement}})
        entry = AuthorityIdentity(getattr(session, {method!r}), "instance-root")
        args = {bound_args}
    else:
        class_session = sessions_module.SessionRedirectMixin()
        class_session.context = context
        original = semantic_authority(
            sessions_module.SessionRedirectMixin, {method!r}, "class-original"
        )
        entry = AuthorityIdentity(class_replacement, "class-replacement")
        class_session.expected = entry
        patch = register_semantic_patch(
            Patch(
                "class-root-patch", original, class_replacement, original,
                "before-actions",
            ),
            sessions_module.SessionRedirectMixin,
            {method!r},
        )
        patches = (patch,)
        args = {class_args}
    action = Action(
        "semantic-call", entry, "__call__", args, OrderedDict(),
        outcome="outcome-" + mode,
    )
    scenarios.append(Scenario(
        "scenario-replacement-" + mode, {operation!r}, entry,
        action.args, action.kwargs, (action,), patches, context, (),
    ))
subject = tuple(scenarios)
controls = {{
    "schema": "phase-a-v6",
    "metadata": OrderedDict((("version", 6), ("scenario_count", 3))),
}}
def observer(subject):
    rows = []
    for scenario in subject:
        context = scenario.context
        tag, value = context.holders[scenario.actions[0].outcome]
        anchors = context.observables["anchors"]
        rows.append((scenario.name, tag, {result_expr}, list(context.events)))
    return rows
result = case_result({case_id!r}, tuple(scenarios), {operation!r}, controls, observer)
"""


