def test_corrected_phase_a_sources_have_one_candidate_owned_result() -> None:
    assert _CORRECTED_CASE_IDS == (
        "M01",
        "M03",
        "M04",
        "M06",
        "M08",
        "A01",
        "A02",
        "A04",
        "A05",
        "A06",
        "A08",
        "E01",
        "E03",
        "E04",
        "E05",
        "E06",
        "E07",
        "R01",
        "R02",
        "R03",
        "R04",
        "R07",
        "T01",
        "T03",
        "T04",
        "T06",
        "T07",
        "T08",
    )
    for case_id in _CORRECTED_CASE_IDS:
        source = _CASES[case_id]
        assert "_CORRECTIONS" not in source
        tree = ast.parse(source)
        case_calls = [
            node
            for node in ast.walk(tree)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "case_result"
        ]
        assert len(case_calls) == 1
        result_assignments = [
            (index, node)
            for index, node in enumerate(tree.body)
            if isinstance(node, ast.Assign)
            and [target.id for target in node.targets if isinstance(target, ast.Name)]
            == ["result"]
        ]
        assert len(result_assignments) == 1
        result_index, result_assignment = result_assignments[0]
        assert result_assignment.value is case_calls[0]
        assert isinstance(result_assignment.value.args[1], ast.Name)
        assert isinstance(result_assignment.value.args[3], ast.Name)
        assert isinstance(result_assignment.value.args[4], ast.Name)
        result_names = (
            result_assignment.value.args[1].id,
            result_assignment.value.args[3].id,
            result_assignment.value.args[4].id,
        )
        assert result_names in {
            ("combined_subject", "combined_controls", "oracle_call"),
            ("v6_subject", "v6_controls", "v6_observer"),
        }

        top_level_names: dict[str, int] = {}
        for index, node in enumerate(tree.body):
            if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                top_level_names[node.name] = index
            elif isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        top_level_names[target.id] = index
        for name in result_names:
            assert top_level_names[name] < result_index
        if result_names[0] == "combined_subject":
            assert top_level_names["adversarial_subject"] < result_index
            assert top_level_names["adversarial_controls"] < result_index
            assert top_level_names["adversarial_oracle_call"] < result_index
            combined_oracle = [
                node
                for node in tree.body
                if isinstance(node, ast.FunctionDef) and node.name == "oracle_call"
            ][-1]
            called_names = {
                node.func.id
                for node in ast.walk(combined_oracle)
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
            }
            assert called_names == {
                "_original_oracle_call",
                "adversarial_oracle_call",
            }


