def test_v6_candidate_receives_complete_owned_payloads(case_id: str) -> None:
    if case_id in _V6_REDIRECT_OUTCOME_COUNTS:
        expected_outcomes = _V6_REDIRECT_OUTCOME_COUNTS[case_id]
    elif case_id == "T02":
        expected_outcomes = 1
    else:
        expected_outcomes = _V6_REAL_OUTCOME_COUNTS[case_id]
    current_case = {"source": dedent(_SESSION_HELPERS + _CASES[case_id])}
    oracle = run_oracle_case(current_case)
    assert oracle.observations["exception"] is None
    assert oracle.stderr == ""

    ownership_setup = f"""
if target == "rewrite":
    def v6_complete_owned_payload_stub(subject, operation, controls):
        assert controls["schema"] == "phase-a-v6"
        assert type(subject) is tuple and subject
        declared_outcomes = 0
        for scenario in subject:
            assert object.__getattribute__(scenario, "operation") == operation
            actions = object.__getattribute__(scenario, "actions")
            context = object.__getattribute__(scenario, "context")
            holders = object.__getattribute__(context, "holders")
            assert type(actions) is tuple and actions
            for action in actions:
                outcome = object.__getattribute__(action, "outcome")
                if outcome is not None:
                    holders[outcome] = ("return", None)
                    declared_outcomes += 1
            assert holders
        assert declared_outcomes == {expected_outcomes}
        return None
    _requests_rust._session_pipeline_trial = v6_complete_owned_payload_stub
"""
    case = {"source": dedent(_SESSION_HELPERS + ownership_setup + _CASES[case_id])}
    mutant = run_rewrite_case(case)
    assert mutant.stderr == ""
    assert mutant.observations != oracle.observations
    mutant_result = mutant.observations["result"]
    oracle_result = oracle.observations["result"]
    assert (
        mutant.observations["exception"] is not None
        or not isinstance(mutant_result, dict)
        or not isinstance(oracle_result, dict)
        or mutant_result.get("repr") != oracle_result.get("repr")
    )


