def test_v6_m02_blocks_delegation_and_runner_recovery() -> None:
    attack = (
        _M02_NATIVE_STUB
        + r"""
if target == "rewrite":
    native = _requests_rust._session_pipeline_trial
    def delegation_mutant(subject, operation, controls, _native=native):
        scenario = subject[0]
        assert object.__getattribute__(scenario, "patches") == ()
        authority = object.__getattribute__(scenario, "receiver")
        assert type(authority).__slots__ == ("token", "role")
        assert not hasattr(authority, "identity")
        token = object.__getattribute__(authority, "token")
        assert not callable(token)
        ctypes = __import__("ctypes")
        recovered = ctypes.cast(id(token), ctypes.py_object).value
        assert recovered is token
        assert not callable(recovered)
        module = __import__("requests.sessions", fromlist=["merge_setting"])
        try:
            module.merge_setting(object(), None)
        except CandidateCompatibilityPoison:
            pass
        else:
            raise AssertionError("base compatibility entry was callable")
        for owner in (type(scenario), type(scenario.receiver)):
            function = owner.__dict__["__init__"]
            function_globals = function.__globals__
            runner = function_globals.get("oracle_call")
            registry = function_globals.get("_AUTHORITY_REGISTRY")
            assert type(registry) is CandidateRunnerPoison
            assert runner is None or type(runner) is CandidateRunnerPoison
            if runner is not None:
                try:
                    runner()
                except CandidateCompatibilityPoison:
                    pass
                else:
                    raise AssertionError("runner global was callable")
        return _native(subject, operation, controls)
    _requests_rust._session_pipeline_trial = delegation_mutant
"""
    )
    case = {"source": dedent(_SESSION_HELPERS + attack + _CASES["M02"])}
    rewrite = run_rewrite_case(case)
    assert rewrite.observations["exception"] is None
    assert rewrite.observations["result"]["repr"] == "[True, True, True]"


