_E06_NATIVE_STUB = r"""
if target == "rewrite":
    def v6_e06_native_stub(subject, operation, controls):
        module = __import__("requests.sessions", fromlist=["Session"])
        ordered = __import__("collections", fromlist=["OrderedDict"]).OrderedDict

        def live_key_error_type(controller):
            if "KeyError" in module.__dict__:
                return module.__dict__["KeyError"]
            if not controller.contains("KeyError"):
                raise NameError("name 'KeyError' is not defined")
            return controller.get("KeyError")

        for scenario in subject:
            context = object.__getattribute__(scenario, "context")
            holders = object.__getattribute__(context, "holders")
            action = object.__getattribute__(scenario, "actions")[0]
            invocation = object.__getattribute__(action, "receiver")
            state = object.__getattribute__(invocation, "state")
            mode = object.__getattribute__(state, "mode")
            request = object.__getattribute__(state, "request")
            session = object.__getattribute__(state, "session")
            supplied = object.__getattribute__(state, "supplied")
            missing = object()
            original_key_error = module.__dict__.get("KeyError", missing)
            builtins_controller = object.__getattribute__(
                state, "builtins_controller"
            )
            original_builtin_key_error = builtins_controller.get(
                "KeyError", missing
            )
            original_prepared = module._is_prepared
            original_urlparse = module.urlparse
            original_resolve = module.resolve_proxies
            original_get_auth = module.get_auth_from_url
            original_basic = module._basic_auth_str
            ordered.clear(object.__getattribute__(request, "_headers"))
            if mode == "auth-absent":
                object.__setattr__(state, "header_state", "absent")
            else:
                ordered.__setitem__(
                    object.__getattribute__(request, "_headers"),
                    "Proxy-Authorization",
                    object.__getattribute__(state, "old_header_value"),
                )
                object.__setattr__(state, "header_state", "old")
            module._is_prepared = object.__getattribute__(
                state, "prepared_helper"
            )
            module.urlparse = object.__getattribute__(state, "parse_helper")
            module.resolve_proxies = object.__getattribute__(
                state, "resolve_helper"
            )
            module.get_auth_from_url = object.__getattribute__(
                state, "get_auth_helper"
            )
            module._basic_auth_str = original_basic
            try:
                try:
                    prepared_check = module._is_prepared
                    assert prepared_check(request)
                    headers = request.headers
                    parse = module.urlparse
                    url = request.url
                    parsed = parse(url)
                    scheme = parsed.scheme
                    resolver = module.resolve_proxies
                    trust_env = session.trust_env
                    new_proxies = resolver(request, supplied, trust_env)
                    if "Proxy-Authorization" in headers:
                        del headers["Proxy-Authorization"]

                    try:
                        auth_helper = module.get_auth_from_url
                        proxy_url = new_proxies[scheme]
                        auth = auth_helper(proxy_url)
                        username, password = auth
                    except live_key_error_type(builtins_controller):
                        username, password = None, None

                    startswith = scheme.startswith
                    if not startswith("https") and username and password:
                        basic_auth = module._basic_auth_str
                        headers["Proxy-Authorization"] = basic_auth(
                            username, password
                        )
                    returned = new_proxies
                except BaseException as error:
                    if not object.__getattribute__(action, "capture"):
                        raise
                    record = ("error", error)
                else:
                    record = ("return", returned)
            finally:
                object.__setattr__(state, "completed", True)
                module._is_prepared = original_prepared
                module.urlparse = original_urlparse
                module.resolve_proxies = original_resolve
                module.get_auth_from_url = original_get_auth
                module._basic_auth_str = original_basic
                if original_key_error is missing:
                    module.__dict__.pop("KeyError", None)
                else:
                    module.KeyError = original_key_error
                if original_builtin_key_error is missing:
                    builtins_controller.delete("KeyError")
                else:
                    builtins_controller.set(
                        "KeyError", original_builtin_key_error
                    )
            holders[object.__getattribute__(action, "outcome")] = record
        return None
    _requests_rust._session_pipeline_trial = v6_e06_native_stub
"""


_E07_NATIVE_STUB = r"""
if target == "rewrite":
    def v6_e07_native_stub(subject, operation, controls):
        module = __import__("requests.sessions", fromlist=["Session"])
        ordered = __import__("collections", fromlist=["OrderedDict"]).OrderedDict

        def should_strip(old_url, new_url):
            first_parser = module.urlparse
            old_parsed = first_parser(old_url)
            second_parser = module.urlparse
            new_parsed = second_parser(new_url)
            if old_parsed.hostname != new_parsed.hostname:
                return True
            if (
                old_parsed.scheme == "http"
                and old_parsed.port in (80, None)
                and new_parsed.scheme == "https"
                and new_parsed.port in (443, None)
            ):
                return False
            changed_port = old_parsed.port != new_parsed.port
            changed_scheme = old_parsed.scheme != new_parsed.scheme
            default_get = module.DEFAULT_PORTS.get
            old_scheme = old_parsed.scheme
            default_port = (default_get(old_scheme, None), None)
            if (
                not changed_scheme
                and old_parsed.port in default_port
                and new_parsed.port in default_port
            ):
                return False
            return changed_port or changed_scheme

        for scenario in subject:
            context = object.__getattribute__(scenario, "context")
            holders = object.__getattribute__(context, "holders")
            action = object.__getattribute__(scenario, "actions")[0]
            invocation = object.__getattribute__(action, "receiver")
            state = object.__getattribute__(invocation, "state")
            family = object.__getattribute__(state, "family")
            if family == "strip":
                original_urlparse = module.urlparse
                original_ports = module.DEFAULT_PORTS
                module.urlparse = object.__getattribute__(state, "parser_one")
                module.DEFAULT_PORTS = object.__getattribute__(
                    state, "early_ports_forbidden"
                )
                try:
                    try:
                        returned = should_strip(
                            object.__getattribute__(state, "old_url"),
                            object.__getattribute__(state, "new_url"),
                        )
                    except BaseException as error:
                        if not object.__getattribute__(action, "capture"):
                            raise
                        record = ("error", error)
                    else:
                        record = ("return", returned)
                finally:
                    object.__setattr__(state, "completed", True)
                    module.urlparse = original_urlparse
                    module.DEFAULT_PORTS = original_ports
            else:
                headers = object.__getattribute__(state, "headers")
                ordered.clear(headers)
                if object.__getattribute__(state, "kind") != "rebuild-auth-absent":
                    ordered.__setitem__(
                        headers,
                        "Authorization",
                        object.__getattribute__(state, "old_header_value"),
                    )
                    object.__setattr__(state, "header_state", "old")
                else:
                    object.__setattr__(state, "header_state", "absent")
                object.__setattr__(state, "prepared_auth", None)
                prepared = object.__getattribute__(state, "prepared")
                object.__setattr__(
                    prepared,
                    "current_prepare",
                    object.__getattribute__(state, "early_prepare_forbidden"),
                )
                original_prepared = module._is_prepared
                original_netrc = module.get_netrc_auth
                module._is_prepared = object.__getattribute__(
                    state, "prepared_one"
                )
                module.get_netrc_auth = object.__getattribute__(
                    state, "eager_netrc_forbidden"
                )
                try:
                    try:
                        response = object.__getattribute__(state, "response")
                        original_request = response.request
                        first_prepared = module._is_prepared
                        assert first_prepared(original_request)
                        second_prepared = module._is_prepared
                        assert second_prepared(prepared)
                        live_headers = prepared.headers
                        original_url = original_request.url
                        url = prepared.url
                        if "Authorization" in live_headers:
                            strip_method = object.__getattribute__(
                                state, "session"
                            ).should_strip_auth
                            if strip_method(original_url, url):
                                del live_headers["Authorization"]
                        session = object.__getattribute__(state, "session")
                        trust_env = session.trust_env
                        if trust_env:
                            netrc = module.get_netrc_auth
                            new_auth = netrc(url)
                        else:
                            new_auth = None
                        if new_auth is not None:
                            prepare_auth = prepared.prepare_auth
                            prepare_auth(new_auth)
                        returned = None
                    except BaseException as error:
                        if not object.__getattribute__(action, "capture"):
                            raise
                        record = ("error", error)
                    else:
                        record = ("return", returned)
                finally:
                    object.__setattr__(state, "completed", True)
                    module._is_prepared = original_prepared
                    module.get_netrc_auth = original_netrc
            holders[object.__getattribute__(action, "outcome")] = record
        return None
    _requests_rust._session_pipeline_trial = v6_e07_native_stub
"""


def test_v6_m06_native_dispatch_ignores_scenario_order_and_batch_count() -> None:
    batched_stub = (
        _M06_NATIVE_STUB
        + r"""
if target == "rewrite":
    def v6_m06_batched_stub(
        subject, operation, controls,
        _dispatch=_requests_rust._session_pipeline_trial,
    ):
        batches = (subject[5:12], subject[12:] + subject[:5])
        for batch in batches:
            _dispatch(batch, operation, controls)
        return None
    _requests_rust._session_pipeline_trial = v6_m06_batched_stub
"""
    )
    oracle = run_oracle_case({"source": dedent(_SESSION_HELPERS + _CASES["M06"])})
    rewrite = run_rewrite_case(
        {"source": dedent(_SESSION_HELPERS + batched_stub + _CASES["M06"])}
    )
    assert oracle.observations["exception"] is None
    assert rewrite.observations == oracle.observations
    assert rewrite.stderr == oracle.stderr == ""


