def test_v6_e_family_alternative_mutant_inventory_is_fixed() -> None:
    mutants = _V6_E_FAMILY_ALTERNATIVE_MUTANTS
    assert len(mutants) == 34
    assert len({(case_id, name) for case_id, name, _, _ in mutants}) == 34
    assert {
        case_id: sum(row_case == case_id for row_case, _, _, _ in mutants)
        for case_id in _V6_ENVIRONMENT_FAMILY_IDS
    } == {"E01": 5, "E03": 6, "E04": 5, "E05": 5, "E06": 7, "E07": 6}
    for case_id, name, old, new in mutants:
        assert case_id in _V6_ENVIRONMENT_FAMILY_IDS
        assert name and old and new and old != new


