def test_v6_a06_exit_retained_postcondition_is_exact() -> None:
    mutant = (
        _A06_NATIVE_STUB
        + r"""
if target == "rewrite":
    v6_a06_correct = _requests_rust._session_pipeline_trial
    def v6_a06_postcondition_mutant(
        subject, operation, controls, _correct=v6_a06_correct
    ):
        returned = _correct(subject, operation, controls)
        for scenario in subject:
            invocation = scenario.actions[0].receiver
            state = object.__getattribute__(invocation, "state")
            if object.__getattribute__(state, "mode") == "exit-retained":
                object.__setattr__(
                    state,
                    "replacement_token",
                    object.__getattribute__(state, "handler_token"),
                )
                break
        return returned
    _requests_rust._session_pipeline_trial = v6_a06_postcondition_mutant
"""
    )
    case = {"source": dedent(_SESSION_HELPERS + mutant + _CASES["A06"])}
    oracle = run_oracle_case(case)
    rewrite = run_rewrite_case(case)
    assert oracle.observations["exception"] is None
    exception = rewrite.observations["exception"]
    assert isinstance(exception, dict)
    assert exception["mro"][0]["name"] == "ScenarioSchemaError"
    assert exception["args"] == ["candidate mutated sealed record"]


