def test_v6_a08_observer_source_is_inspection_only() -> None:
    tree = ast.parse(_CASES["A08"])
    observer = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name == "v6_observer"
    )
    forbidden_methods = {
        "__next__",
        "close",
        "finish",
        "read",
        "release_conn",
    }
    forbidden_names = {"iter", "next"}
    calls = [
        node
        for node in ast.walk(observer)
        if isinstance(node, ast.Call)
        and (
            isinstance(node.func, ast.Attribute)
            and node.func.attr in forbidden_methods
            or isinstance(node.func, ast.Name)
            and node.func.id in forbidden_names
        )
    ]
    assert calls == []


