        returned = _candidate(subject, operation, controls)
        connection_slots = (
            "generation", "identity", "invalidated", "closed",
            "close_count", "rejoined",
        )
        lease_slots = (
            "state", "connection", "active", "orphaned", "completed",
        )
        pool_slots = ("state", "generation", "responses", "connections")
        def clone_slots(source, names):
            source_type = object.__getattribute__(source, "__class__")
            cloned = object.__new__(source_type)
            for name in names:
                object.__setattr__(
                    cloned,
                    name,
                    object.__getattribute__(source, name),
                )
            return cloned
        def clone_dict_object(source):
            source_type = object.__getattribute__(source, "__class__")
            cloned = object.__new__(source_type)
            source_values = object.__getattribute__(source, "__dict__")
            cloned_values = object.__getattribute__(cloned, "__dict__")
