def _a08_pool_map_mutant(mutation: str) -> str:
    return (
        _A08_NATIVE_STUB
        + f"""
if target == "rewrite":
    v6_a08_pool_candidate = _requests_rust._session_pipeline_trial
    def v6_a08_pool_map_mutant(
        subject, operation, controls, _candidate=v6_a08_pool_candidate
    ):
        returned = _candidate(subject, operation, controls)
        for scenario in subject:
            context = object.__getattribute__(scenario, "context")
            holders = object.__getattribute__(context, "holders")
            state = holders["state"]
            if object.__getattribute__(state, "mode") != "lifecycle":
                continue
            pool = object.__getattribute__(state, "pool_adapter")
            responses = object.__getattribute__(pool, "responses")
            connections = object.__getattribute__(pool, "connections")
{_A08_POOL_MAP_MUTATIONS[mutation]}
            return returned
        raise AssertionError("lifecycle scenario was not found")
    _requests_rust._session_pipeline_trial = v6_a08_pool_map_mutant
"""
    )


