def test_v6_a08_allows_unrelated_lifecycle_state_mutation() -> None:
    mutant = (
        _A08_NATIVE_STUB
        + r"""
if target == "rewrite":
    v6_a08_unrelated_candidate = _requests_rust._session_pipeline_trial
    def v6_a08_unrelated_state_mutant(
        subject, operation, controls, _candidate=v6_a08_unrelated_candidate
    ):
        returned = _candidate(subject, operation, controls)
        for scenario in subject:
            context = object.__getattribute__(scenario, "context")
            holders = object.__getattribute__(context, "holders")
            state = holders["state"]
            if object.__getattribute__(state, "mode") == "lifecycle":
                object.__setattr__(state, "mapping", object())
                return returned
        raise AssertionError("lifecycle scenario was not found")
    _requests_rust._session_pipeline_trial = v6_a08_unrelated_state_mutant
"""
    )
    case = {"source": dedent(_SESSION_HELPERS + mutant + _CASES["A08"])}
    oracle = run_oracle_case(case)
    rewrite = run_rewrite_case(case)
    assert oracle.observations["exception"] is None
    assert rewrite.observations == oracle.observations
    assert rewrite.stderr == oracle.stderr == ""


