@pytest.mark.parametrize(
    ("case_id", "outcome_index", "mutation_kind"),
    [
        (case_id, outcome_index, mutation_kind)
        for case_id, count in _V6_REAL_OUTCOME_COUNTS.items()
        for outcome_index in range(count)
        for mutation_kind in ("value", "tag")
    ],
)
def test_v6_real_observers_validate_every_declared_outcome(
    case_id: str, outcome_index: int, mutation_kind: str
) -> None:
    mutant = (
        _V6_REAL_NATIVE_STUBS[case_id]
        + f"""
if target == "rewrite":
    v6_outcome_candidate = _requests_rust._session_pipeline_trial
    def v6_outcome_mutant(subject, operation, controls):
        returned = v6_outcome_candidate(subject, operation, controls)
        current = 0
        for scenario in subject:
            context = object.__getattribute__(scenario, "context")
            holders = object.__getattribute__(context, "holders")
            for action in object.__getattribute__(scenario, "actions"):
                outcome = object.__getattribute__(action, "outcome")
                if outcome is None:
                    continue
                if current == {outcome_index}:
                    record = holders[outcome]
                    if {mutation_kind!r} == "value":
                        holders[outcome] = (record[0], object())
                    else:
                        changed_tag = (
                            "error" if record[0] == "return" else "return"
                        )
                        holders[outcome] = (changed_tag, record[1])
                    return returned
                current += 1
        raise AssertionError("declared outcome index was not found")
    _requests_rust._session_pipeline_trial = v6_outcome_mutant
"""
    )
    case = {"source": dedent(_SESSION_HELPERS + mutant + _CASES[case_id])}
    oracle = run_oracle_case(case)
    rewrite = run_rewrite_case(case)
    assert oracle.observations["exception"] is None
    assert rewrite.observations != oracle.observations


