def _v6_semantic_patch_error_source() -> str:
    token = secrets.token_hex(12)
    outcome = "outcome-" + secrets.token_hex(8)
    skipped_outcome = "outcome-" + secrets.token_hex(8)
    return f"""
v6_original_patch_target = sessions_module.get_netrc_auth
v6_marker = KeyboardInterrupt("semantic-patch-stop")
v6_context = ScenarioContext(
    {token!r},
    markers=(v6_marker,),
    holders=OrderedDict(),
    mutations=("events",),
)


class V6SemanticPatchStop:
    __slots__ = ("context", "marker")

    def __init__(self, context, marker):
        self.context = context
        self.marker = marker

    def __call__(self, url):
        self.context.events.append(["patched-call", url])
        raise self.marker


v6_stop = V6SemanticPatchStop(v6_context, v6_marker)
v6_identity = semantic_authority(sessions_module, "get_netrc_auth")
v6_patch = register_semantic_patch(
    Patch(
        "patch-" + {token!r},
        v6_identity,
        v6_stop,
        v6_identity,
        "before-actions",
    ),
    sessions_module,
    "get_netrc_auth",
)
v6_args = ("http://example.test/",)
v6_kwargs = OrderedDict()
v6_actions = (
    Action(
        "patched-call",
        v6_patch,
        "__call__",
        v6_args,
        v6_kwargs,
        outcome={outcome!r},
        capture=True,
    ),
    Action(
        "patched-call",
        v6_patch,
        "__call__",
        ("http://example.test/must-not-run",),
        OrderedDict(),
        outcome={skipped_outcome!r},
        capture=True,
    ),
)
v6_subject = (
    Scenario(
        "scenario-" + {token!r},
        "semantic-patch-checkpoint",
        v6_patch,
        v6_args,
        v6_kwargs,
        v6_actions,
        (v6_patch,),
        v6_context,
        (v6_stop,),
    ),
)
v6_controls = {{
    "schema": "phase-a-v6",
    "metadata": OrderedDict([
        ("version", 6),
        ("scenario_count", 1),
    ]),
}}


def v6_observer(
    subject, _object=object, _ordered=OrderedDict, _tuple=tuple, _list=list
):
    context = _object.__getattribute__(subject[0], "context")
    holders = _object.__getattribute__(context, "holders")
    record = _ordered.__getitem__(holders, {outcome!r})
    assert _tuple.__getitem__(record, 0) == "error"
    error = _tuple.__getitem__(record, 1)
    marker = _tuple.__getitem__(
        _object.__getattribute__(context, "markers"), 0
    )
    return {{
        "same": error is marker,
        "terminated": {skipped_outcome!r} not in holders,
        "events": _list(_object.__getattribute__(context, "events")),
    }}


result = case_result(
    "semantic-patch-checkpoint",
    v6_subject,
    "semantic-patch-checkpoint",
    v6_controls,
    v6_observer,
)
assert sessions_module.get_netrc_auth is v6_original_patch_target
"""


_SEMANTIC_PATCH_ERROR_STUB = r"""
if target == "rewrite":
    def semantic_patch_error_stub(subject, operation, controls):
        scenario = subject[0]
        action = scenario.actions[0]
        module = __import__("requests.sessions", fromlist=["get_netrc_auth"])
        try:
            module.get_netrc_auth(*action.args, **action.kwargs)
        except BaseException as error:
            record = ("error", error)
        else:
            raise AssertionError("semantic error authority returned")
        scenario.context.holders[action.outcome] = record
        return None
    _requests_rust._session_pipeline_trial = semantic_patch_error_stub
"""


def test_v6_semantic_patch_error_identity_and_restoration() -> None:
    source = _v6_semantic_patch_error_source()
    oracle = run_oracle_case({"source": dedent(_SESSION_HELPERS + source)})
    rewrite = run_rewrite_case(
        {"source": dedent(_SESSION_HELPERS + _SEMANTIC_PATCH_ERROR_STUB + source)}
    )
    assert oracle.observations["exception"] is None
    assert rewrite.observations == oracle.observations
    assert rewrite.observations["result"]["repr"] == (
        "{'same': True, 'terminated': True, 'events': "
        "[['patched-call', 'http://example.test/']]}"
    )


