@pytest.mark.parametrize("case_id", _CASE_IDS)
def test_v6_payload_does_not_expose_oracle_runner_globals(case_id: str) -> None:
    malicious_setup = r"""
if target == "rewrite":
    v6_audit_sentinel = SystemExit("runner-traversal-audit-complete")
    def v6_malicious_stub(
        subject, operation, controls, _sentinel=v6_audit_sentinel
    ):
        stack = [subject, controls]
        seen = set()
        forbidden = {
            "oracle_call", "_original_oracle_call", "adversarial_oracle_call"
        }
        while stack:
            value = stack.pop()
            identity = id(value)
            if identity in seen:
                continue
            seen.add(identity)
            if isinstance(value, dict):
                stack.extend(value.keys())
                stack.extend(value.values())
                continue
            if isinstance(value, (list, tuple, set, frozenset)):
                stack.extend(value)
                continue
            globals_map = getattr(value, "__globals__", None)
            if isinstance(globals_map, dict):
                assert forbidden.isdisjoint(globals_map)
            call = getattr(type(value), "__call__", None)
            call_globals = getattr(call, "__globals__", None)
            if isinstance(call_globals, dict):
                assert forbidden.isdisjoint(call_globals)
            values = getattr(value, "__dict__", None)
            if isinstance(values, dict):
                stack.extend(values.values())
        raise _sentinel
    _requests_rust._session_pipeline_trial = v6_malicious_stub
"""
    case = {"source": dedent(_SESSION_HELPERS + malicious_setup + _CASES[case_id])}
    rewrite = run_rewrite_case(case)
    exception = rewrite.observations["exception"]
    assert isinstance(exception, dict)
    assert exception["mro"][0]["name"] == "SystemExit"
    assert exception["args"] == ["runner-traversal-audit-complete"]


