@pytest.mark.parametrize("case_id", _CASE_IDS)
def test_v6_candidate_boundary_poison_blocks_compatibility_delegation(
    case_id: str,
) -> None:
    poison_setup = r"""
if target == "rewrite":
    v6_audit_sentinel = SystemExit("boundary-poison-audit-complete")
    def v6_delegating_stub(
        subject, operation, controls, _sentinel=v6_audit_sentinel
    ):
        module = __import__("requests.sessions", fromlist=["Session"])
        if operation == "merge-setting":
            callback = module.merge_setting
        elif operation == "merge-hooks":
            callback = module.merge_hooks
        else:
            method = {
                "prepare-request": "prepare_request",
                "prepare-request-auth": "prepare_request",
                "mount": "mount",
                "get-adapter": "get_adapter",
                "construct": "__init__",
                "pickle": "__getstate__",
                "close": "close",
                "close-reuse": "close",
                "active-stream-close": "close",
                "environment": "merge_environment_settings",
                "environment-proxies": "merge_environment_settings",
                "environment-ca": "merge_environment_settings",
                "environment-merge": "merge_environment_settings",
                "rebuild-proxies": "rebuild_proxies",
                "rebuild-auth": "rebuild_auth",
                "redirect-target": "get_redirect_target",
                "redirect-method": "rebuild_method",
                "send": "send",
                "send-error": "send",
                "send-reentrant-mutation": "send",
                "digest-redirect": "send",
            }.get(operation, "resolve_redirects")
            owner = (
                module.SessionRedirectMixin
                if method in {
                    "rebuild_proxies", "rebuild_auth", "get_redirect_target",
                    "rebuild_method", "resolve_redirects",
                }
                else module.Session
            )
            callback = getattr(owner, method)
        try:
            callback()
        except CandidateCompatibilityPoison:
            raise _sentinel
        raise AssertionError("compatibility implementation remained callable")
    _requests_rust._session_pipeline_trial = v6_delegating_stub
"""
    case = {"source": dedent(_SESSION_HELPERS + poison_setup + _CASES[case_id])}
    rewrite = run_rewrite_case(case)
    exception = rewrite.observations["exception"]
    assert isinstance(exception, dict)
    assert exception["mro"][0]["name"] == "SystemExit"
    assert exception["args"] == ["boundary-poison-audit-complete"]
